{"command":"cat > src/config.rs <<'RS'
use anyhow::{anyhow, Context};
use clap::{Arg, ArgAction, Command};
use serde::{Deserialize, Deserializer};
use std::collections::HashMap;
use std::fs::File;
use std::io::Read;
use std::path::PathBuf;

pub const VERSION: &str = "0.37.1 (63c65c2 2026-06-11)";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Target {
    CortexM,
    Msp430,
    RISCV,
    XtensaLX,
    Mips,
    None,
}
impl<'de> Deserialize<'de> for Target {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        // Use a helper enum to get serde's variant error messages exactly.
        #[derive(Deserialize)]
        enum H {
            #[serde(rename = "cortex-m")]
            CortexM,
            #[serde(rename = "msp430")]
            Msp430,
            #[serde(rename = "riscv")]
            RISCV,
            #[serde(rename = "xtensa-lx")]
            XtensaLX,
            #[serde(rename = "mips")]
            Mips,
            #[serde(rename = "none")]
            None,
        }
        Ok(match H::deserialize(d)? {
            H::CortexM => Target::CortexM,
            H::Msp430 => Target::Msp430,
            H::RISCV => Target::RISCV,
            H::XtensaLX => Target::XtensaLX,
            H::Mips => Target::Mips,
            H::None => Target::None,
        })
    }
}
impl Default for Target { fn default() -> Self { Target::CortexM } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Edition { E2021, E2024 }
impl<'de> Deserialize<'de> for Edition {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        enum H { #[serde(rename="2021")] E2021, #[serde(rename="2024")] E2024 }
        Ok(match H::deserialize(d)? { H::E2021=>Edition::E2021, H::E2024=>Edition::E2024 })
    }
}
impl Default for Edition { fn default() -> Self { Edition::E2021 } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SourceType { Xml, Yaml, Json }
impl<'de> Deserialize<'de> for SourceType {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        enum H { #[serde(rename="xml")] Xml, #[serde(rename="yaml")] Yaml, #[serde(rename="json")] Json }
        Ok(match H::deserialize(d)? { H::Xml=>SourceType::Xml, H::Yaml=>SourceType::Yaml, H::Json=>SourceType::Json })
    }
}
impl Default for SourceType { fn default() -> Self { SourceType::Xml } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IdentFormatsTheme { Legacy }
impl<'de> Deserialize<'de> for IdentFormatsTheme {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        enum H { #[serde(rename="legacy")] Legacy }
        Ok(match H::deserialize(d)? { H::Legacy=>IdentFormatsTheme::Legacy })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Case { Constant, Pascal, Snake }
impl<'de> Deserialize<'de> for Case {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        enum H { #[serde(rename="constant")] Constant, #[serde(rename="pascal")] Pascal, #[serde(rename="snake")] Snake }
        Ok(match H::deserialize(d)? { H::Constant=>Case::Constant, H::Pascal=>Case::Pascal, H::Snake=>Case::Snake })
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct IdentFormat {
    #[serde(default)]
    pub case: Option<Case>,
    #[serde(default)]
    pub prefix: String,
    #[serde(default)]
    pub suffix: String,
}
impl IdentFormat {
    pub fn new(case: Option<Case>, prefix: &str, suffix: &str) -> Self { Self { case, prefix: prefix.to_string(), suffix: suffix.to_string() } }
    pub fn parse_str(s: &str) -> Option<Self> {
        // used for completeness, not CLI (CLI handled separately)
        let case = match s { ""|"unchanged"=>None, "p"|"pascal"=>Some(Case::Pascal), "c"|"constant"=>Some(Case::Constant), "s"|"snake"=>Some(Case::Snake), _=>return None };
        Some(Self::new(case, "", ""))
    }
}

#[derive(Debug, Clone)]
pub struct IdentFormats(pub HashMap<String, IdentFormat>);

impl IdentFormats {
    pub fn default_theme() -> Self {
        let mut m = HashMap::new();
        let mut ins = |k: &str, c: Option<Case>, suf: &str| { m.insert(k.to_string(), IdentFormat::new(c, "", suf)); };
        // "new" theme
        ins("cluster", Some(Case::Pascal), "");
        ins("cluster_accessor", Some(Case::Snake), "");
        ins("cluster_mod", Some(Case::Snake), "");
        ins("enum_name", Some(Case::Pascal), "");
        ins("enum_read_name", Some(Case::Pascal), "");
        ins("enum_value", Some(Case::Pascal), "");
        ins("enum_value_accessor", Some(Case::Snake), "");
        ins("enum_write_name", Some(Case::Pascal), "WO");
        ins("field_accessor", Some(Case::Snake), "");
        ins("field_reader", Some(Case::Pascal), "R");
        ins("field_writer", Some(Case::Pascal), "W");
        ins("interrupt", None, "");
        ins("peripheral", Some(Case::Pascal), "");
        ins("peripheral_feature", Some(Case::Snake), "");
        ins("peripheral_mod", Some(Case::Snake), "");
        ins("peripheral_singleton", Some(Case::Snake), "");
        ins("peripheral_spec", Some(Case::Pascal), "Spec");
        ins("register", Some(Case::Pascal), "");
        ins("register_accessor", Some(Case::Snake), "");
        ins("register_mod", Some(Case::Snake), "");
        ins("register_spec", Some(Case::Pascal), "Spec");
        Self(m)
    }
    pub fn legacy_theme() -> Self {
        let mut m = HashMap::new();
        let mut ins = |k: &str, c: Case, suf: &str| { m.insert(k.to_string(), IdentFormat::new(Some(c), "", suf)); };
        ins("cluster", Case::Constant, "");
        ins("cluster_accessor", Case::Snake, "");
        ins("cluster_mod", Case::Snake, "");
        ins("enum_name", Case::Constant, "_A");
        ins("enum_read_name", Case::Constant, "_A");
        ins("enum_value", Case::Constant, "");
        ins("enum_value_accessor", Case::Snake, "");
        ins("enum_write_name", Case::Constant, "_AW");
        ins("field_accessor", Case::Snake, "");
        ins("field_reader", Case::Constant, "_R");
        ins("field_writer", Case::Constant, "_W");
        ins("interrupt", Case::Constant, "");
        ins("peripheral", Case::Constant, "");
        ins("peripheral_feature", Case::Snake, "");
        ins("peripheral_mod", Case::Snake, "");
        ins("peripheral_singleton", Case::Constant, "");
        ins("peripheral_spec", Case::Constant, "_SPEC");
        ins("register", Case::Constant, "");
        ins("register_accessor", Case::Snake, "");
        ins("register_mod", Case::Snake, "");
        ins("register_spec", Case::Constant, "_SPEC");
        Self(m)
    }
    pub fn get(&self, key: &str) -> &IdentFormat {
        // All known keys are present after building; unknown fallback should not happen.
        self.0.get(key).unwrap_or_else(|| self.0.get("register").unwrap())
    }
}

