pub fn build_command() -> Command {
    // dynamic ident format help
    let keys: Vec<String> = IdentFormats::default_theme().0.keys().cloned().collect();
    let ident_help = format!(
        "Specify `-f type:prefix:case:suffix` to change default ident formatting.\nAllowed values of `type` are {:?}.\nAllowed cases are `unchanged` (''), `pascal` ('p'), `constant` ('c') and `snake` ('s').\n",
        keys
    );
    // Leak string for clap static lifetime
    let ident_help: &'static str = Box::leak(ident_help.into_boxed_str());
    Command::new("svd2rust")
        .version(VERSION)
        .about("Generate a Rust API from SVD files")
        .arg(Arg::new("input").short('i').value_name("FILE").help("Input SVD file"))
        .arg(Arg::new("output_dir").short('o').long("output-dir").value_name("PATH").help("Directory to place generated files"))
        .arg(Arg::new("config").short('c').long("config").value_name("TOML_FILE").help("Config TOML file"))
        .arg(Arg::new("settings_file").long("settings").value_name("YAML_FILE").help("Target-specific settings YAML file"))
        .arg(Arg::new("edition").long("edition").value_name("YEAR").help("Rust edition of generated code"))
        .arg(Arg::new("target").long("target").value_name("ARCH").help("Target architecture"))
        .arg(Arg::new("atomics").long("atomics").action(ArgAction::SetTrue).help("Generate atomic register modification API"))
        .arg(Arg::new("atomics_feature").long("atomics-feature").value_name("FEATURE").help("add feature gating for atomic register modification API"))
        .arg(Arg::new("ignore_groups").long("ignore-groups").action(ArgAction::SetTrue).help("Don't add alternateGroup name as prefix to register name"))
        .arg(Arg::new("keep_list").long("keep-list").action(ArgAction::SetTrue).help("Keep lists when generating code of dimElement, instead of trying to generate arrays"))
        .arg(Arg::new("generic_mod").short('g').long("generic-mod").action(ArgAction::SetTrue).help("Push generic mod in separate file"))
        .arg(Arg::new("feature_group").long("feature-group").action(ArgAction::SetTrue).help("Use group_name of peripherals as feature"))
        .arg(Arg::new("feature_peripheral").long("feature-peripheral").action(ArgAction::SetTrue).help("Use independent cfg feature flags for each peripheral"))
        .arg(Arg::new("ident_format").short('f').long("ident-format").value_name("ident_format").action(ArgAction::Append).help(ident_help))
        .arg(Arg::new("ident_formats_theme").long("ident-formats-theme").value_name("THEME").help("A set of `ident_format` settings. `new` or `legacy`"))
        .arg(Arg::new("field_names_for_enums").long("field-names-for-enums").action(ArgAction::SetTrue).help("Use field name for enumerations even when enumeratedValues has a name"))
        .arg(Arg::new("max_cluster_size").long("max-cluster-size").action(ArgAction::SetTrue).help("Use array increment for cluster size"))
        .arg(Arg::new("impl_debug").long("impl-debug").action(ArgAction::SetTrue).help("implement Debug for readable blocks and registers"))
        .arg(Arg::new("impl_debug_feature").long("impl-debug-feature").value_name("FEATURE").help("Add feature gating for block and register debug implementation"))
        .arg(Arg::new("impl_defmt").long("impl-defmt").value_name("FEATURE").help("Add automatic defmt implementation for enumerated values"))
        .arg(Arg::new("make_mod").short('m').long("make-mod").action(ArgAction::SetTrue).help("Create mod.rs instead of lib.rs, without inner attributes"))
        .arg(Arg::new("skip_crate_attributes").long("skip-crate-attributes").action(ArgAction::SetTrue).help("Do not generate crate attributes"))
        .arg(Arg::new("strict").short('s').long("strict").action(ArgAction::SetTrue).help("Make advanced checks due to parsing SVD"))
        .arg(Arg::new("source_type").long("source-type").value_name("source_type").help("Specify file/stream format"))
        .arg(Arg::new("reexport_core_peripherals").long("reexport-core-peripherals").action(ArgAction::SetTrue).help("For Cortex-M target reexport peripherals from cortex-m crate"))
        .arg(Arg::new("reexport_interrupt").long("reexport-interrupt").action(ArgAction::SetTrue).help("Reexport interrupt macro from cortex-m-rt like crates"))
        .arg(Arg::new("base_address_shift").short('b').long("base-address-shift").value_name("base_address_shift")
            .help("Add offset to all base addresses on all peripherals in the SVD file.")
            .long_help("Add offset to all base addresses on all peripherals in the SVD file.\nUseful for soft-cores where the peripheral address range isn't necessarily fixed.\nIgnore this option if you are not building your own FPGA based soft-cores."))
        .arg(Arg::new("log_level").short('l').long("log").value_name("log_level")
            .value_parser(clap::builder::PossibleValuesParser::new(["off","error","warn","info","debug","trace"]))
            .help("Choose which messages to log (overrides RUST_LOG)"))
}

fn deep_merge(base: &mut serde_json::Value, over: serde_json::Value) {
    match (base, over) {
        (serde_json::Value::Object(b), serde_json::Value::Object(o)) => {
            for (k, v) in o {
                match b.get_mut(&k) {
                    Some(existing) => deep_merge(existing, v),
                    None => { b.insert(k, v); }
                }
            }
        }
        (b, o) => { *b = o; }
    }
}

fn parse_case(s: &str) -> Option<Option<Case>> {
    match s {
        "" | "unchanged" => Some(None),
        "p" | "pascal" => Some(Some(Case::Pascal)),
        "c" | "constant" => Some(Some(Case::Constant)),
        "s" | "snake" => Some(Some(Case::Snake)),
        _ => None,
    }
}

fn parse_ident_format_cli(s: &str, valid: &std::collections::HashSet<String>) -> Option<(String, IdentFormat)> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() < 2 { return None; }
    let ty = parts[0];
    if !valid.contains(ty) { return None; }
    let (prefix, case_str, suffix): (&str, &str, &str) = match parts.len() {
        2 => ("", parts[1], ""),
        3 => (parts[1], parts[2], ""),
        _ => (parts[1], parts[2], parts[3]),
    };
    let case = parse_case(case_str)?;
    Some((ty.to_string(), IdentFormat::new(case, prefix, suffix)))
}

impl Config {
    pub fn from_matches(matches: &clap::ArgMatches) -> anyhow::Result<Self> {
        // Determine config file path
        let config_path: PathBuf = matches.get_one::<String>("config").cloned().unwrap_or_else(|| "svd2rust.toml".to_string()).into();

        // Parser #2: TOML file (if exists as file and can be opened)
        let mut merged = serde_json::Value::Object(serde_json::Map::new());
        if config_path.is_file() {
            if let Ok(mut file) = File::open(&config_path) {
                let mut content = String::new();
                file.read_to_string(&mut content).map_err(|e| {
                    anyhow::Error::from(e).context("$Failed read data to buffer")
                }).context("Failed to parse value for parser #2")?;
                let toml_val: toml::Value = toml::Table::from_str_helper(&content)
                    .map_err(|e| anyhow::Error::from(e).context("Failed parse TOML"))
                    .context("Failed to parse value for parser #2")?;
                let json_val = serde_json::to_value(toml_val).unwrap_or(serde_json::Value::Null);
                if json_val.is_object() {
                    merged = json_val;
                }
            }
        }

        // CLI layer
        let mut cli_obj = serde_json::Map::new();
        let string_keys = [
            "input","output_dir","settings_file","edition","target","atomics_feature",
            "ident_formats_theme","impl_debug_feature","impl_defmt","source_type","base_address_shift","log_level",
        ];
        for k in string_keys {
            if matches.value_source(k) == Some(clap::parser::ValueSource::CommandLine) {
                if let Some(v) = matches.get_one::<String>(k) {
                    cli_obj.insert(k.to_string(), serde_json::Value::String(v.clone()));
                }
            }
        }
        let bool_keys = ["atomics","ignore_groups","keep_list","generic_mod","feature_group","feature_peripheral","field_names_for_enums","max_cluster_size","impl_debug","make_mod","skip_crate_attributes","strict","reexport_core_peripherals","reexport_interrupt"];
        for k in bool_keys {
            if matches.value_source(k) == Some(clap::parser::ValueSource::CommandLine) {
                if matches.get_flag(k) {
                    cli_obj.insert(k.to_string(), serde_json::Value::Bool(true));
                }
            }
        }
        // ident_format multi
        if matches.value_source("ident_format") == Some(clap::parser::ValueSource::CommandLine) {
            let valid: std::collections::HashSet<String> = IdentFormats::default_theme().0.keys().cloned().collect();
            let mut map = serde_json::Map::new();
            if let Some(vals) = matches.get_many::<String>("ident_format") {
                for v in vals {
                    if let Some((ty, fmt)) = parse_ident_format_cli(v, &valid) {
                        let mut entry = serde_json::Map::new();
                        entry.insert("case".into(), match fmt.case { None=>serde_json::Value::Null, Some(Case::Pascal)=>serde_json::json!("pascal"), Some(Case::Constant)=>serde_json::json!("constant"), Some(Case::Snake)=>serde_json::json!("snake") });
                        entry.insert("prefix".into(), serde_json::Value::String(fmt.prefix));
                        entry.insert("suffix".into(), serde_json::Value::String(fmt.suffix));
                        map.insert(ty, serde_json::Value::Object(entry));
                    }
                }
            }
            cli_obj.insert("ident_formats".into(), serde_json::Value::Object(map));
        }
        deep_merge(&mut merged, serde_json::Value::Object(cli_obj));

        let de: ConfigDe = serde_json::from_value(merged).map_err(|e| anyhow::Error::from(e)).context("Failed to deserialize value")?;

        // Build final ident formats
        let mut ident_formats = match de.ident_formats_theme {
            Some(IdentFormatsTheme::Legacy) => IdentFormats::legacy_theme(),
            None => IdentFormats::default_theme(),
        };
        for (k, v) in de.ident_formats { ident_formats.0.insert(k, v); }

        Ok(Config {
            edition: de.edition, target: de.target, atomics: de.atomics, atomics_feature: de.atomics_feature,
            generic_mod: de.generic_mod, make_mod: de.make_mod, skip_crate_attributes: de.skip_crate_attributes,
            ignore_groups: de.ignore_groups, keep_list: de.keep_list, strict: de.strict,
            feature_group: de.feature_group, feature_peripheral: de.feature_peripheral,
            max_cluster_size: de.max_cluster_size, impl_debug: de.impl_debug, impl_debug_feature: de.impl_debug_feature,
            impl_defmt: de.impl_defmt, output_dir: de.output_dir, input: de.input, source_type: de.source_type,
            log_level: de.log_level, interrupt_link_section: de.interrupt_link_section,
            reexport_core_peripherals: de.reexport_core_peripherals, reexport_interrupt: de.reexport_interrupt,
            ident_formats, ident_formats_theme: de.ident_formats_theme, field_names_for_enums: de.field_names_for_enums,
            base_address_shift: de.base_address_shift, settings_file: de.settings_file, settings: de.settings,
        })
    }
}

// Helper trait to parse toml table: toml::Value parsing via FromStr
trait FromStrHelper { fn from_str_helper(s: &str) -> Result<toml::Value, toml::de::Error>; }
impl FromStrHelper for toml::Table {
    fn from_str_helper(s: &str) -> Result<toml::Value, toml::de::Error> { s.parse::<toml::Value>() }
}
RS"}

