#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Case { Constant, Pascal, Snake }
impl<'de> Deserialize<'de> for Case {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
