{"command":"cat > src/xml.rs <<'RS'
#[derive(Debug, Clone)]
pub enum Child {
    Element(Node),
    Text(String),
}
#[derive(Debug, Clone)]
pub struct Node {
    pub tag: String,
    pub attrs: Vec<(String, String)>,
    pub children: Vec<Child>,
    pub line: usize,
    pub col: usize,
}
impl Node {
    pub fn local_name(&self) -> &str {
        self.tag.rsplit(':').next().unwrap_or(&self.tag)
    }
    pub fn elements<'a>(&'a self) -> impl Iterator<Item=&'a Node> + 'a {
        self.children.iter().filter_map(|c| match c { Child::Element(n)=>Some(n), _=>None })
    }
    pub fn get_child(&self, name: &str) -> Option<&Node> {
        self.elements().find(|n| n.local_name()==name)
    }
    pub fn get_children<'a>(&'a self, name: &'a str) -> impl Iterator<Item=&'a Node> + 'a {
        self.elements().filter(move |n| n.local_name()==name)
    }
    pub fn text(&self) -> Option<&str> {
        for c in &self.children { if let Child::Text(t)=c { return Some(t); } }
        None
    }
    pub fn attr(&self, name: &str) -> Option<&str> {
        self.attrs.iter().find(|(k,_)| k.rsplit(':').next().unwrap_or(k)==name).map(|(_,v)| v.as_str())
    }
    pub fn pos_str(&self) -> String { format!("{}:{}", self.line, self.col) }
}

fn line_col(s: &str, byte_pos: usize) -> (usize, usize) {
    let mut line=1usize; let mut col=1usize;
    for (i,ch) in s.char_indices() {
        if i>=byte_pos { break; }
        if ch=='\n' { line+=1; col=1; } else { col+=1; }
    }
    (line,col)
}
fn err_at(s:&str, pos:usize, msg:String) -> String {
    let (l,c)=line_col(s,pos); format!("{} at {}:{}", msg, l, c)
}

struct Parser<'a> { s:&'a str, bytes:&'a [u8], pos:usize }
impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> { self.bytes.get(self.pos).copied() }
    fn starts(&self, pat:&str) -> bool { self.s[self.pos..].starts_with(pat) }
    fn eof(&self) -> bool { self.pos>=self.s.len() }
    fn skip_ws(&mut self) { while matches!(self.peek(), Some(b' '|b'\t'|b'\n'|b'\r')) { self.pos+=1; } }

    fn parse_name(&mut self) -> Result<String,String> {
        let start=self.pos;
        match self.peek() {
            Some(b) if b==b'_' || b==b':' || (b as char).is_ascii_alphabetic() || b>=0x80 => {},
            _ => { return Err(err_at(self.s, self.pos, "invalid name token".into())); }
        }
        while let Some(b)=self.peek() {
            let ch=b as char;
            if ch.is_ascii_alphanumeric() || matches!(ch, '_'|'-'|'.'|':') || b>=0x80 { self.pos+=1; } else { break; }
        }
        Ok(self.s[start..self.pos].to_string())
    }

    fn decode_entities(&self, raw:&str, raw_start:usize) -> Result<String,String> {
        if !raw.contains('&') {
            // check ]]> 
            if let Some(idx)=raw.find("]]>") {
                return Err(err_at(self.s, raw_start+idx+2, "']]>'".to_string() + " is not allowed inside a character data"))
                // note message built below corrected
            }
            return Ok(raw.to_string());
        }
        let mut out=String::new(); let mut rest=raw; let mut offset=raw_start;
        loop {
            match rest.find('&') {
                None => { 
                    if let Some(idx)=rest.find("]]>") { let (l,c)=line_col(self.s, offset+idx+2); return Err(format!("']]>' at {}:{} is not allowed inside a character data",l,c)); }
                    out.push_str(rest); break; }
                Some(i) => {
                    let before=&rest[..i];
                    if let Some(idx)=before.find("]]>") { let (l,c)=line_col(self.s, offset+idx+2); return Err(format!("']]>' at {}:{} is not allowed inside a character data",l,c)); }
                    out.push_str(before);
                    let ent_start=offset+i;
                    let after=&rest[i+1..];
                    match after.find(';') {
                        Some(j) => {
                            let ent=&after[..j];
                            // entity must be valid token chars and no spaces / <
                            if ent.is_empty() || ent.contains(|ch:char| !(ch.is_ascii_alphanumeric() || ch=='#')) {
                                return Err(err_at(self.s, ent_start, "malformed entity reference".into()));
                            }
                            match ent {
                                "amp"=>out.push('&'), "lt"=>out.push('<'), "gt"=>out.push('>'), "quot"=>out.push('"'), "apos"=>out.push('\''),
                                _ if ent.starts_with("#x") || ent.starts_with("#X") => {
                                    let hex=&ent[2..];
                                    match u32::from_str_radix(hex,16).ok().and_then(char::from_u32) { Some(ch)=>out.push(ch), None=>return Err(err_at(self.s, ent_start, "malformed entity reference".into())) }
                                }
                                _ if ent.starts_with('#') => {
                                    let dec=&ent[1..];
                                    match dec.parse::<u32>().ok().and_then(char::from_u32) { Some(ch)=>out.push(ch), None=>return Err(err_at(self.s, ent_start, "malformed entity reference".into())) }
                                }
                                _ => {
                                    // unknown entity reference 'unknown'
                                    return Err(err_at(self.s, ent_start, format!("unknown entity reference '{}'", ent)));
                                }
                            }
                            offset = ent_start + 1 + j + 1;
                            rest=&after[j+1..];
                        }
                        None => return Err(err_at(self.s, ent_start, "malformed entity reference".into()))
                    }
                }
            }
        }
        Ok(out)
    }

    fn skip_misc(&mut self) -> Result<(),String> {
        loop {
            self.skip_ws();
            if self.starts("<?") {
                match self.s[self.pos..].find("?>") { Some(i)=>{self.pos+=i+2;} None=>{self.pos=self.s.len();} }
            } else if self.starts("<!--") {
                match self.s[self.pos..].find("-->") { Some(i)=>{self.pos+=i+3;} None=>{self.pos=self.s.len();} }
            } else if self.starts("<!DOCTYPE") || self.starts("<!doctype") {
                return Err("XML with DTD detected".into());
            } else if self.starts("<!") {
                // other declarations? treat as DTD?
                return Err("XML with DTD detected".into());
            } else { break; }
        }
        Ok(())
    }

    fn parse_element(&mut self) -> Result<Node,String> {
        let elem_start=self.pos;
        // assume '<'
        self.pos+=1;
        let tag=self.parse_name()?;
        let (line,col)=line_col(self.s, elem_start);
        let mut attrs:Vec<(String,String)>=Vec::new();
        let self_closing: bool;
        loop {
            self.skip_ws();
            if self.eof() { return Err("the root node was opened but never closed".into()); }
            if self.starts("/>") { self.pos+=2; self_closing=true; break; }
            if self.peek()==Some(b'>') { self.pos+=1; self_closing=false; break; }
            if self.peek()==Some(b'/') {
                // "/ >" case: expected '>' not ' '
                self.pos+=1;
                let p=self.pos;
                let ch=self.peek().map(|b| b as char).unwrap_or(' ');
                return Err(err_at(self.s,p,format!("expected '>' not '{}'",ch)));
            }
            // attribute
            let attr_start=self.pos;
            let aname=self.parse_name()?;
            if attrs.iter().any(|(k,_)| k==&aname) {
                let (l,c)=line_col(self.s, attr_start);
                return Err(format!("attribute '{}' at {}:{} is already defined", aname,l,c));
            }
            self.skip_ws();
            if self.peek()==Some(b'=') { self.pos+=1; }
            self.skip_ws();
            let quote=self.peek();
            if quote!=Some(b'"') && quote!=Some(b'\'') {
                let ch=quote.map(|b| b as char).unwrap_or('?');
                let p=self.pos;
                return Err(err_at(self.s,p,format!("expected a quote not '{}'",ch)));
            }
            let q=quote.unwrap(); self.pos+=1;
