            if self.eof() { return Err("the root node was opened but never closed".into()); }
            if self.starts("</") {
                let close_start=self.pos;
                self.pos+=2;
                let cname=self.parse_name()?;
                self.skip_ws();
                if self.peek()==Some(b'>') { self.pos+=1; }
                if cname!=node.tag {
                    return Err(err_at(self.s, close_start, format!("expected '{}' tag, not '{}'", node.tag, cname)));
                }
                break;
            } else if self.starts("<!--") {
                match self.s[self.pos..].find("-->") { Some(i)=>{self.pos+=i+3;} None=>{self.pos=self.s.len();} }
            } else if self.starts("<![CDATA[") {
                self.pos+=9;
                match self.s[self.pos..].find("]]>") {
                    Some(i)=>{ let txt=self.s[self.pos..self.pos+i].to_string(); node.children.push(Child::Text(txt)); self.pos+=i+3; }
                    None=>{ self.pos=self.s.len(); }
                }
            } else if self.starts("<?") {
                match self.s[self.pos..].find("?>") { Some(i)=>{self.pos+=i+2;} None=>{self.pos=self.s.len();} }
            } else if self.starts("<!DOCTYPE") {
                return Err("XML with DTD detected".into());
            } else if self.peek()==Some(b'<') {
                let child=self.parse_element()?;
                node.children.push(Child::Element(child));
            } else {
                let tstart=self.pos;
                while let Some(b)=self.peek() { if b==b'<' {break;} self.pos+=1; }
                let raw=&self.s[tstart..self.pos];
                if !raw.is_empty() {
                    // check ]]> with special message format
                    if let Some(idx)=raw.find("]]>") {
                        let (l,c)=line_col(self.s, tstart+idx+2);
                        return Err(format!("']]>' at {}:{} is not allowed inside a character data",l,c));
                    }
                    let txt=self.decode_entities(raw,tstart)?;
                    node.children.push(Child::Text(txt));
                }
            }
        }
        Ok(node)
    }
}

pub fn parse_document(input: &str) -> Result<Node,String> {
    let s = input.strip_prefix('\u{feff}').unwrap_or(input);
    let mut p=Parser{s, bytes:s.as_bytes(), pos:0};
    p.skip_misc()?;
    if p.eof() { return Err("the document does not have a root node".into()); }
    if p.peek()!=Some(b'<') || p.starts("</") {
        return Err(err_at(s,p.pos,"unknown token".into()));
    }
    // check for invalid like "< "
    let root=p.parse_element()?;
    // trailing misc only
    let save=p.pos;
    p.skip_misc()?;
    // skip_misc skipped ws; if anything left unknown token at its pos
    // But skip_misc leaves pos at first non-misc char
    let _=save;
    if !p.eof() {
        return Err(err_at(s,p.pos,"unknown token".into()));
    }
    Ok(root)
}
RS"}

