// ===== XML parsing helpers =====
fn child_text(node:&Node, tag:&str) -> Option<String> {
    node.get_child(tag).and_then(|n| n.text().map(|s| s.to_string()))
}
fn child_text_trimmed(node:&Node, tag:&str) -> Option<String> { child_text(node,tag) }

fn parsing_ctx(ty:&str, name:Option<&str>, node:&Node) -> String {
    match name { Some(n)=>format!("Parsing {} `{}` at {}", ty, n, node.pos_str()), None=>format!("Parsing unknown {} at {}", ty, node.pos_str()) }
}
fn in_ctx(ty:&str, name:&str) -> String { format!("In {} `{}`", ty, name) }

pub fn parse_svd_int_raw(s:&str) -> Result<u128,String> {
    let t=s.trim();
    // Returns Err with ParseIntError-like message (without "Failed to parse" wrapper)
    let parse_err_msg = |e: std::num::ParseIntError| e.to_string();
    if let Some(hex)=t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        u128::from_str_radix(hex,16).map_err(parse_err_msg)
    } else if let Some(bin)=t.strip_prefix("0b").or_else(|| t.strip_prefix("0B")).or_else(|| t.strip_prefix('#')) {
        let cleaned: String = bin.chars().map(|c| if c=='x' || c=='X' { '0' } else { c }).collect();
        u128::from_str_radix(&cleaned,2).map_err(parse_err_msg)
    } else {
        t.parse::<u128>().map_err(parse_err_msg)
    }
}
fn int_convert<T: TryFrom<u128>>(v:u128) -> Result<T,String> {
    T::try_from(v).map_err(|_| "number too large to fit in target type".to_string())
}

fn leaf_err(child:&Node, msg:String) -> anyhow::Error {
    anyhow!(msg).context(format!("Parsing unknown {} at {}", child.local_name(), child.pos_str()))
}

// Parse optional child integer; Ok(None) if child missing or no text
fn get_opt_int<T: TryFrom<u128>>(node:&Node, tag:&str) -> anyhow::Result<Option<T>> {
    let Some(child)=node.get_child(tag) else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    let v=parse_svd_int_raw(text).and_then(int_convert::<T>).map_err(|e| leaf_err(child, format!("Failed to parse `{}`", e)))?;
    Ok(Some(v))
}
fn get_opt_bool(node:&Node, tag:&str) -> anyhow::Result<Option<bool>> {
    let Some(child)=node.get_child(tag) else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    let t=text.trim();
    match t { "true"|"1"=>Ok(Some(true)), "false"|"0"=>Ok(Some(false)), _=>Err(leaf_err(child, format!("The content of the element could not be parsed to a boolean value {}: provided string was not `true` or `false`", t))) }
}
fn get_opt_access(node:&Node) -> anyhow::Result<Option<Access>> {
    let Some(child)=node.get_child("access") else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    let t=text.trim();
    Ok(Some(match t {
        "read-only"=>Access::ReadOnly, "write-only"=>Access::WriteOnly, "read-write"=>Access::ReadWrite, "writeOnce"=>Access::WriteOnce, "readOnce"=>Access::ReadOnce,
        _=>return Err(leaf_err(child, format!("unknown access variant '{}' found", t)))
    }))
}
fn parse_properties(node:&Node) -> anyhow::Result<RegisterProperties> {
    Ok(RegisterProperties { size:get_opt_int(node,"size")?, access:get_opt_access(node)?, reset_value:get_opt_int(node,"resetValue")?, reset_mask:get_opt_int(node,"resetMask")? })
}
fn get_opt_mwv(node:&Node) -> anyhow::Result<Option<ModifiedWriteValues>> {
    let Some(child)=node.get_child("modifiedWriteValues") else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    Ok(Some(match text.trim() {
        "oneToClear"=>ModifiedWriteValues::OneToClear,"oneToSet"=>ModifiedWriteValues::OneToSet,"oneToToggle"=>ModifiedWriteValues::OneToToggle,
        "zeroToClear"=>ModifiedWriteValues::ZeroToClear,"zeroToSet"=>ModifiedWriteValues::ZeroToSet,"zeroToToggle"=>ModifiedWriteValues::ZeroToToggle,
        "clear"=>ModifiedWriteValues::Clear,"set"=>ModifiedWriteValues::Set,"modify"=>ModifiedWriteValues::Modify,
        other=>return Err(leaf_err(child, format!("Invalid modifiedWriteValues variant, found {}", other)))
    }))
}
fn get_opt_read_action(node:&Node) -> anyhow::Result<Option<ReadAction>> {
    let Some(child)=node.get_child("readAction") else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    Ok(Some(match text.trim() {
        "clear"=>ReadAction::Clear,"set"=>ReadAction::Set,"modify"=>ReadAction::Modify,"modifyExternal"=>ReadAction::ModifyExternal,
        other=>return Err(leaf_err(child, format!("Invalid readAction variant, found {}", other)))
    }))
}
fn get_opt_data_type(node:&Node) -> anyhow::Result<Option<DataType>> {
    let Some(child)=node.get_child("dataType") else { return Ok(None) };
    let Some(text)=child.text() else { return Ok(None) };
    Ok(Some(match text.trim() {
        "uint8_t"=>DataType::Uint8,"uint16_t"=>DataType::Uint16,"uint32_t"=>DataType::Uint32,"uint64_t"=>DataType::Uint64,
        "int8_t"=>DataType::Int8,"int16_t"=>DataType::Int16,"int32_t"=>DataType::Int32,"int64_t"=>DataType::Int64,
        "uint8_t *"=>DataType::Uint8Ptr,"uint16_t *"=>DataType::Uint16Ptr,"uint32_t *"=>DataType::Uint32Ptr,"uint64_t *"=>DataType::Uint64Ptr,
        "int8_t *"=>DataType::Int8Ptr,"int16_t *"=>DataType::Int16Ptr,"int32_t *"=>DataType::Int32Ptr,"int64_t *"=>DataType::Int64Ptr,
        other=>return Err(leaf_err(child, format!("Invalid datatype variant, found {}", other)))
    }))
}

fn parse_write_constraint(node:&Node) -> anyhow::Result<Option<WriteConstraint>> {
    let Some(wc)=node.get_child("writeConstraint") else { return Ok(None) };
    // find first element child
    let Some(first)=wc.elements().next() else {
        return Err(anyhow!("Unknown write constraint").context(parsing_ctx("writeConstraint",None,wc)));
    };
    match first.local_name() {
        "writeAsRead" => { let v=get_opt_bool(wc,"writeAsRead")?.unwrap_or(false); Ok(Some(WriteConstraint::WriteAsRead(v))) }
        "useEnumeratedValues" => { let v=get_opt_bool(wc,"useEnumeratedValues")?.unwrap_or(false); Ok(Some(WriteConstraint::UseEnumeratedValues(v))) }
        "range" => {
            // range parse direct errors under Parsing unknown range
            let range_node=first;
            let minimum = match get_opt_int::<u64>(range_node,"minimum")? { Some(v)=>v, None=>return Err(anyhow!("Expected a <minimum> tag, found none").context(parsing_ctx("range",None,range_node))) };
            let maximum = match get_opt_int::<u64>(range_node,"maximum")? { Some(v)=>v, None=>return Err(anyhow!("Expected a <maximum> tag, found none").context(parsing_ctx("range",None,range_node))) };
            Ok(Some(WriteConstraint::Range(WriteConstraintRange{minimum,maximum})))
        }
        _ => Err(anyhow!("Unknown write constraint").context(parsing_ctx("writeConstraint",None,wc)))
    }
}

fn parse_dim_index_text(text:&str) -> Vec<String> {
    // SVD DimIndex: comma separated values or ranges using '-' like "A-Z", "0-3", or enumerated format
    // Original svd parser parses with custom logic; implement common cases.
    let t=text.trim();
    let mut out=Vec::new();
    for part in t.split(',') {
        let p=part.trim();
        if p.is_empty() { continue; }
        // Range detection: pattern X-Y where single dash and both sides are same kind (numeric or single char)
        // Need be careful with names containing '-'
        let mut expanded=None;
        if let Some((a,b)) = p.split_once('-') {
            let a=a.trim(); let b=b.trim();
            if let (Ok(ai),Ok(bi))=(a.parse::<i64>(), b.parse::<i64>()) {
                if ai<=bi && (bi-ai)<100000 { expanded=Some((ai..=bi).map(|x| x.to_string()).collect::<Vec<_>>()); }
            } else if a.chars().count()==1 && b.chars().count()==1 {
                let ac=a.chars().next().unwrap(); let bc=b.chars().next().unwrap();
                if ac<=bc { expanded=Some((ac as u32..=bc as u32).filter_map(char::from_u32).map(|c| c.to_string()).collect()); }
            }
        }
        if let Some(v)=expanded { out.extend(v); } else { out.push(p.to_string()); }
    }
    out
}

fn parse_dim(node:&Node) -> anyhow::Result<DimElement> {
    let dim=get_opt_int(node,"dim")?;
    let dim_increment=get_opt_int(node,"dimIncrement")?;
    let dim_index = match node.get_child("dimIndex") {
        Some(ch) => match ch.text() { Some(t)=>Some(parse_dim_index_text(t)), None=>None },
        None=>None
    };
    let dim_name=child_text(node,"dimName");
    let dim_array_index = match node.get_child("dimArrayIndex") {
        Some(ch) => {
            let mut vals=Vec::new();
            for ev in ch.get_children("enumeratedValue") { vals.push(parse_enumerated_value(ev)?); }
            Some(DimArrayIndex{ header_enum_name: child_text(ch,"headerEnumName"), enumerated_values: vals })
        } None=>None
    };
    Ok(DimElement{dim, dim_increment, dim_index, dim_name, dim_array_index})
}

fn parse_enumerated_value(node:&Node) -> anyhow::Result<EnumeratedValue> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else {
        return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("enumeratedValue",None,node)));
    };
    let description=child_text(node,"description");
    let value=get_opt_int::<u64>(node,"value").map_err(|e| e.context(in_ctx("enumeratedValue",&name)))?;
    let is_default=get_opt_bool(node,"isDefault").map_err(|e| e.context(in_ctx("enumeratedValue",&name)))?;
    if value.is_none() && is_default.is_none() {
        return Err(anyhow!("`EnumeratedValue error: EnumeratedValue has no `value` or `is_default`").context(parsing_ctx("enumeratedValue",Some(&name),node)));
    }
    // isDefault empty element handling: in SVD, <isDefault>true</isDefault>; also <isDefault/> might mean None above then error etc.
    Ok(EnumeratedValue{name,description,value,is_default})
}

fn parse_enumerated_values(node:&Node) -> anyhow::Result<EnumeratedValues> {
    let name=child_text(node,"name");
    let header_enum_name=child_text(node,"headerEnumName");
    // usage parse; errors NOT wrapped by enumeratedValues (direct leaf returns)
    let usage = match node.get_child("usage") {
        Some(ch) => match ch.text() { Some(t)=>Some(match t.trim() { "read"=>Usage::Read,"write"=>Usage::Write,"read-write"=>Usage::ReadWrite, _=>return Err(leaf_err(ch,"Unknown usage variant".into())) }), None=>None }, None=>None
    };
    let mut values=Vec::new();
    for ev in node.get_children("enumeratedValue") { values.push(parse_enumerated_value(ev)?); }
    let derived_from=node.attr("derivedFrom").map(|s| s.to_string());
    if values.is_empty() && derived_from.is_none() {
        return Err(anyhow!("`EnumeratedValues error: EnumeratedValues is empty").context(parsing_ctx("enumeratedValues",name.as_deref(),node)));
    }
    Ok(EnumeratedValues{name,header_enum_name,usage,derived_from,values})
}

fn parse_field(node:&Node) -> anyhow::Result<FieldInfo> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("field",None,node))); };
    // child errors wrapped with In field
    let wrap = |e:anyhow::Error| e.context(in_ctx("field",&name));
    let dim=parse_dim(node).map_err(wrap.clone())?;
    let description=child_text(node,"description");
    // bit range determination: errors directly wrapped Parsing field (as observed) for bitrange syntax issues,
    // but scalar parsing errors (bitOffset invalid int) would be leaf + In field? We'll decide: use get_opt_int returns leaf err; wrapping In field.
    let bit_offset_opt=get_opt_int::<u32>(node,"bitOffset").map_err(wrap.clone())?;
    let bit_width_opt=get_opt_int::<u32>(node,"bitWidth").map_err(wrap.clone())?;
    let (bit_offset, bit_width) = if let (Some(o),Some(w))=(bit_offset_opt,bit_width_opt) {
        (o,w)
    } else if let Some(br_node)=node.get_child("bitRange") {
        // bitRange text like [7:0]
        let txt=br_node.text().unwrap_or("").trim();
        let parsed = (|| -> Option<(u32,u32)> {
            let inner=txt.strip_prefix('[')?.strip_suffix(']')?;
            let (a,b)=inner.split_once(':')?;
            let msb:u32=a.trim().parse().ok()?; let lsb:u32=b.trim().parse().ok()?;
            if msb<lsb { return None; }
            Some((lsb, msb-lsb+1))
        })();
        match parsed { Some(v)=>v, None=>return Err(anyhow!("Bit range invalid, Syntax").context(parsing_ctx("field",Some(&name),node))) }
    } else if node.get_child("lsb").is_some() || node.get_child("msb").is_some() {
        let lsb=get_opt_int::<u32>(node,"lsb");
        let msb=get_opt_int::<u32>(node,"msb");
        match (lsb,msb) {
            (Ok(Some(l)),Ok(Some(m))) if m>=l => (l, m-l+1),
            _=>return Err(anyhow!("Bit range invalid, MsbLsb").context(parsing_ctx("field",Some(&name),node)))
        }
    } else if bit_offset_opt.is_some() || bit_width_opt.is_some() {
        // only one present
        return Err(anyhow!("Bit range invalid, Syntax").context(parsing_ctx("field",Some(&name),node)));
    } else {
        return Err(anyhow!("Bit range invalid, Syntax").context(parsing_ctx("field",Some(&name),node)));
    };
    let access=get_opt_access(node).map_err(wrap.clone())?;
    let mwv=get_opt_mwv(node).map_err(wrap.clone())?;
    let read_action=get_opt_read_action(node).map_err(wrap.clone())?;
    let write_constraint=parse_write_constraint(node).map_err(wrap.clone())?;
    let mut enums=Vec::new();
    for evn in node.get_children("enumeratedValues") { enums.push(parse_enumerated_values(evn).map_err(wrap.clone())?); }
    Ok(FieldInfo{ derived_from: node.attr("derivedFrom").map(|s|s.to_string()), dim, name, description, bit_offset, bit_width, access, enumerated_values:enums, write_constraint, read_action, modified_write_values:mwv })
}

fn parse_register(node:&Node) -> anyhow::Result<RegisterInfo> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("register",None,node))); };
    // addressOffset required (direct)
    if node.get_child("addressOffset").and_then(|n| n.text()).is_none() {
        return Err(anyhow!("Expected a <addressOffset> tag, found none").context(parsing_ctx("register",Some(&name),node)));
    }
    let wrap=|e:anyhow::Error| e.context(in_ctx("register",&name));
    let address_offset=get_opt_int::<u32>(node,"addressOffset").map_err(wrap.clone())?.unwrap();
    let dim=parse_dim(node).map_err(wrap.clone())?;
    let properties=parse_properties(node).map_err(wrap.clone())?;
    let mwv=get_opt_mwv(node).map_err(wrap.clone())?;
    let read_action=get_opt_read_action(node).map_err(wrap.clone())?;
    let data_type=get_opt_data_type(node).map_err(wrap.clone())?;
    let write_constraint=parse_write_constraint(node).map_err(wrap.clone())?;
    let fields = match node.get_child("fields") {
        Some(fnode)=>{ let mut v=Vec::new(); for f in fnode.get_children("field") { v.push(parse_field(f).map_err(wrap.clone())?); } Some(v) }
        None=>None
    };
    Ok(RegisterInfo{
        derived_from: node.attr("derivedFrom").map(|s|s.to_string()), dim, name: name.clone(),
        display_name: child_text(node,"displayName"), description: child_text(node,"description"),
        alternate_group: child_text(node,"alternateGroup"), alternate_register: child_text(node,"alternateRegister"),
        address_offset, properties, data_type, modified_write_values:mwv, write_constraint, read_action, fields,
    })
}

fn parse_cluster(node:&Node) -> anyhow::Result<ClusterInfo> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("cluster",None,node))); };
    if node.get_child("addressOffset").and_then(|n| n.text()).is_none() {
        return Err(anyhow!("Expected a <addressOffset> tag, found none").context(parsing_ctx("cluster",Some(&name),node)));
    }
    let wrap=|e:anyhow::Error| e.context(in_ctx("cluster",&name));
    let address_offset=get_opt_int::<u32>(node,"addressOffset").map_err(wrap.clone())?.unwrap();
    let dim=parse_dim(node).map_err(wrap.clone())?;
    let properties=parse_properties(node).map_err(wrap.clone())?;
    let mut children=Vec::new();
    for child in node.elements() {
        match child.local_name() {
            "register"=>children.push(RegisterCluster::Register(parse_register(child).map_err(wrap.clone())?)),
            "cluster"=>children.push(RegisterCluster::Cluster(parse_cluster(child).map_err(wrap.clone())?)),
            _=>{}
        }
    }
    Ok(ClusterInfo{ derived_from: node.attr("derivedFrom").map(|s|s.to_string()), dim, name: name.clone(), display_name: child_text(node,"displayName"), description: child_text(node,"description"), alternate_cluster: child_text(node,"alternateCluster"), header_struct_name: child_text(node,"headerStructName"), address_offset, properties, children })
}

fn parse_interrupt(node:&Node) -> anyhow::Result<Interrupt> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("interrupt",None,node))); };
    if node.get_child("value").and_then(|n| n.text()).is_none() {
        return Err(anyhow!("Expected a <value> tag, found none").context(parsing_ctx("interrupt",Some(&name),node)));
    }
    let wrap=|e:anyhow::Error| e.context(in_ctx("interrupt",&name));
    let value=get_opt_int::<u32>(node,"value").map_err(wrap)?.unwrap();
    Ok(Interrupt{name, description: child_text(node,"description"), value})
}

fn parse_address_block(node:&Node) -> anyhow::Result<AddressBlock> {
    // direct missing errors under Parsing unknown addressBlock
    if node.get_child("offset").and_then(|n| n.text()).is_none() { return Err(anyhow!("Expected a <offset> tag, found none").context(parsing_ctx("addressBlock",None,node))); }
    if node.get_child("size").and_then(|n| n.text()).is_none() { return Err(anyhow!("Expected a <size> tag, found none").context(parsing_ctx("addressBlock",None,node))); }
    if node.get_child("usage").and_then(|n| n.text()).is_none() { return Err(anyhow!("Expected a <usage> tag, found none").context(parsing_ctx("addressBlock",None,node))); }
    let offset=get_opt_int::<u32>(node,"offset")?.unwrap();
    let size=get_opt_int::<u32>(node,"size")?.unwrap();
    let usage_node=node.get_child("usage").unwrap();
    let usage=match usage_node.text().unwrap().trim() { "registers"=>AddressBlockUsage::Registers, "buffer"=>AddressBlockUsage::Buffer, "reserved"=>AddressBlockUsage::Reserved, _=>return Err(leaf_err(usage_node,"Unknown usage variant for addressBlock".into())) };
    Ok(AddressBlock{offset,size,usage,protection: child_text(node,"protection")})
}

fn parse_peripheral(node:&Node, strict:bool) -> anyhow::Result<Peripheral> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("peripheral",None,node))); };
    if node.get_child("baseAddress").and_then(|n| n.text()).is_none() {
        return Err(anyhow!("Expected a <baseAddress> tag, found none").context(parsing_ctx("peripheral",Some(&name),node)));
    }
    let wrap=|e:anyhow::Error| e.context(in_ctx("peripheral",&name));
    let base_address=get_opt_int::<u64>(node,"baseAddress").map_err(wrap.clone())?.unwrap();
    let dim=parse_dim(node).map_err(wrap.clone())?;
    let properties=parse_properties(node).map_err(wrap.clone())?;
    // address blocks (take ... store first? original model may have only one; if multiple, parse all for errors but keep first)
    let mut address_block=None;
    for ab in node.get_children("addressBlock") { let v=parse_address_block(ab).map_err(wrap.clone())?; if address_block.is_none() { address_block=Some(v); } }
    let mut interrupts=Vec::new();
    for inode in node.elements() {
        if inode.local_name()=="interrupt" { interrupts.push(parse_interrupt(inode).map_err(wrap.clone())?); }
        // interrupts may also be wrapped in <interrupts>? SVD schema: directly peripheral/interrupt* (no wrapper). Handle wrapper anyway?
        if inode.local_name()=="interrupts" { for sub in inode.get_children("interrupt") { interrupts.push(parse_interrupt(sub).map_err(wrap.clone())?); } }
    }
    let registers = match node.get_child("registers") {
        Some(rnode)=>{ let mut v=Vec::new(); for child in rnode.elements() { match child.local_name() { "register"=>v.push(RegisterCluster::Register(parse_register(child).map_err(wrap.clone())?)), "cluster"=>v.push(RegisterCluster::Cluster(parse_cluster(child).map_err(wrap.clone())?)), _=>{} } } Some(v) }
        None=>None
    };
    let _=strict;
    Ok(Peripheral{
        derived_from: node.attr("derivedFrom").map(|s|s.to_string()), dim, name: name.clone(),
        version: child_text(node,"version"), description: child_text(node,"description"),
        alternate_peripheral: child_text(node,"alternatePeripheral"), group_name: child_text(node,"groupName"),
        prepend_to_name: child_text(node,"prependToName"), append_to_name: child_text(node,"appendToName"),
        header_struct_name: child_text(node,"headerStructName"), disable_condition: child_text(node,"disableCondition"),
        base_address, properties, address_block, interrupts, registers,
    })
}

fn parse_cpu(node:&Node) -> anyhow::Result<Cpu> {
    let name_opt=child_text(node,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("cpu",None,node))); };
    let direct=|msg:String| anyhow!(msg).context(parsing_ctx("cpu",Some(&name),node));
    // scalar parsing in cpu is NOT wrapped with In cpu (observed)
    // Required fields order: revision, endian, mpuPresent, fpuPresent, nvicPrioBits, vendorSystickConfig
    let revision = match child_text(node,"revision") { Some(v)=>v, None=>return Err(direct("Expected a <revision> tag, found none".into())) };
    // endian: if child exists parse leaf (error Parsing unknown endian); if missing direct
    let endian_node=node.get_child("endian");
    let endian = match endian_node { Some(en)=>match en.text() { Some(t)=>match t.trim() { "little"=>Endian::Little,"big"=>Endian::Big,"selectable"=>Endian::Selectable,"other"=>Endian::Other, other=>return Err(leaf_err(en, format!("Unknown endianness `{}`", other))) }, None=>return Err(direct("Expected a <endian> tag, found none".into())) }, None=>return Err(direct("Expected a <endian> tag, found none".into())) };
    let mpu_present = match get_opt_bool(node,"mpuPresent")? { Some(v)=>v, None=>return Err(direct("Expected a <mpuPresent> tag, found none".into())) };
    let fpu_present = match get_opt_bool(node,"fpuPresent")? { Some(v)=>v, None=>return Err(direct("Expected a <fpuPresent> tag, found none".into())) };
    let nvic_prio_bits = match get_opt_int::<u8>(node,"nvicPrioBits")? { Some(v)=>v, None=>return Err(direct("Expected a <nvicPrioBits> tag, found none".into())) };
    let vendor_systick_config = match get_opt_bool(node,"vendorSystickConfig")? { Some(v)=>v, None=>return Err(direct("Expected a <vendorSystickConfig> tag, found none".into())) };
    Ok(Cpu{
        name, revision, endian, mpu_present, fpu_present,
        fpu_dp:get_opt_bool(node,"fpuDP")?, dsp_present:get_opt_bool(node,"dspPresent")?, icache_present:get_opt_bool(node,"icachePresent")?, dcache_present:get_opt_bool(node,"dcachePresent")?, itcm_present:get_opt_bool(node,"itcmPresent")?, dtcm_present:get_opt_bool(node,"dtcmPresent")?, vtor_present:get_opt_bool(node,"vtorPresent")?,
        device_num_interrupts:get_opt_int(node,"deviceNumInterrupts")?, sau_num_regions:get_opt_int(node,"sauNumRegions")?,
        vendor_id: child_text(node,"vendorId"), nvic_prio_bits, vendor_systick_config,
    })
}

pub fn parse_device_xml(root:&Node, strict:bool) -> anyhow::Result<Device> {
    if root.local_name()!="device" { return Err(anyhow!("Expected a <device> tag, found none")); }
    let name_opt=child_text(root,"name");
    let Some(name)=name_opt.clone() else { return Err(anyhow!("Expected a <name> tag, found none").context(parsing_ctx("device",None,root))); };
    let wrap=|e:anyhow::Error| e.context(in_ctx("device",&name));
    let cpu = match root.get_child("cpu") { Some(cn)=>Some(parse_cpu(cn).map_err(wrap.clone())?), None=>None };
    let properties=parse_properties(root).map_err(wrap.clone())?;
    // peripherals required
    let Some(per_node)=root.get_child("peripherals") else {
        return Err(anyhow!("Expected a <peripherals> tag, found none").context(parsing_ctx("device",Some(&name),root)));
    };
    let mut peripherals=Vec::new();
    for p in per_node.get_children("peripheral") { peripherals.push(parse_peripheral(p, strict).map_err(wrap.clone())?); }
    // remaining scalars
    let address_unit_bits_opt=get_opt_int::<u32>(root,"addressUnitBits").map_err(wrap.clone())?;
    let width_opt=get_opt_int::<u32>(root,"width").map_err(wrap.clone())?;
    let version_opt=child_text(root,"version");
    let description_opt=child_text(root,"description");
    if strict {
        if version_opt.is_none() { return Err(anyhow!("`Build error: `version` must be initialized").context(parsing_ctx("device",Some(&name),root))); }
        if description_opt.is_none() { return Err(anyhow!("`Build error: `description` must be initialized").context(parsing_ctx("device",Some(&name),root))); }
        if address_unit_bits_opt.is_none() { return Err(anyhow!("`Build error: `addressUnitBits` must be initialized").context(parsing_ctx("device",Some(&name),root))); }
        if width_opt.is_none() { return Err(anyhow!("`Build error: `width` must be initialized").context(parsing_ctx("device",Some(&name),root))); }
    }
    if peripherals.is_empty() {
        return Err(anyhow!("`Device error: Device must contain at least one peripheral").context(parsing_ctx("device",Some(&name),root)));
    }
    Ok(Device{
        schema_version: root.attr("schemaVersion").map(|s|s.to_string()),
        vendor: child_text(root,"vendor"), vendor_id: child_text(root,"vendorID"),
        name, version: version_opt.unwrap_or_default(), description: description_opt.unwrap_or_default(),
        license_text: child_text(root,"licenseText"), cpu,
        header_struct_name: child_text(root,"headerStructName"), header_definitions_prefix: child_text(root,"headerDefinitionsPrefix"),
        address_unit_bits: address_unit_bits_opt.unwrap_or(0), width: width_opt.unwrap_or(0), properties, peripherals,
    })
}

pub fn validate_device_json(device:&Device) -> anyhow::Result<()> {
    if device.peripherals.is_empty() {
        // replicate: top display `Device error: ... with source msg
        return Err(anyhow!("Device must contain at least one peripheral").context("`Device error: Device must contain at least one peripheral"));
    }
    Ok(())
}
