    pub fn as_str(&self) -> &'static str { match self { Access::ReadOnly=>"read-only", Access::WriteOnly=>"write-only", Access::ReadWrite=>"read-write", Access::WriteOnce=>"writeOnce", Access::ReadOnce=>"readOnce" } }
