    pub fn address_offset(&self) -> u32 { match self { RegisterCluster::Register(r)=>r.address_offset, RegisterCluster::Cluster(c)=>c.address_offset } }
    pub fn derived_from(&self) -> Option<&str> { match self { RegisterCluster::Register(r)=>r.derived_from.as_deref(), RegisterCluster::Cluster(c)=>c.derived_from.as_deref() } }
    pub fn dim(&self) -> &DimElement { match self { RegisterCluster::Register(r)=>&r.dim, RegisterCluster::Cluster(c)=>&c.dim } }
