use crate::config::{Case, Config};
use proc_macro2::{Ident, Literal, Span};
use std::str::FromStr;

pub fn sanitize(s: &str) -> String {
    s.chars().filter(|c| !matches!(c, ' ' | '-' | '/' | '[' | ']' | '(' | ')')).collect()
}

pub fn to_snake(s: &str) -> String {
    let mut out = String::new();
    let mut prev: Option<char> = None;
    for ch in s.chars() {
        if ch.is_uppercase() && prev.map_or(false, |p| p.is_lowercase()) {
            out.push('_');
        }
        out.extend(ch.to_lowercase());
        prev = Some(ch);
    }
    out
}
pub fn to_constant(s: &str) -> String { to_snake(s).to_uppercase() }

fn split_subwords(seg: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut cur = String::new();
    let mut prev: Option<char> = None;
    for ch in seg.chars() {
        if ch.is_uppercase() && prev.map_or(false, |p| p.is_lowercase()) && !cur.is_empty() {
            words.push(cur);
            cur = String::new();
        }
        cur.push(ch);
        prev = Some(ch);
    }
    if !cur.is_empty() { words.push(cur); }
    words
}
fn pascal_word(w: &str, preserve_first: bool) -> String {
    let mut chars = w.chars();
    match chars.next() {
        None => String::new(),
        Some(first) => {
            let mut out = String::new();
            if preserve_first { out.push(first); } else { out.extend(first.to_uppercase()); }
            for ch in chars { out.extend(ch.to_lowercase()); }
            out
        }
    }
}

pub fn to_pascal(s: &str) -> String {
    if s.is_empty() { return String::new(); }
    if s.chars().all(|c| c=='_') { return "_".to_string(); }
    let lead = s.chars().take_while(|&c| c=='_').count();
    let trail = s.chars().rev().take_while(|&c| c=='_').count();
    let body = s.trim_matches('_');
    if body.is_empty() { return "_".to_string(); }
    // Split body by underscore runs, remembering run lengths between segments
    let mut segments: Vec<String> = Vec::new();
    let mut runs: Vec<usize> = Vec::new(); // runs[i] is underscores before segments[i+1]
    let mut cur = String::new();
    let mut chars = body.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch=='_' {
            let mut run=1;
            while let Some(&'_')=chars.peek() { chars.next(); run+=1; }
            segments.push(cur); cur=String::new(); runs.push(run);
        } else { cur.push(ch); }
    }
    segments.push(cur);

    let mut out = String::new();
    if lead>0 { out.push('_'); }
    for (i, seg) in segments.iter().enumerate() {
        if i>0 {
            let run = runs[i-1];
            let prev_digit = out.chars().last().map_or(false, |c| c.is_ascii_digit());
            let next_digit = seg.chars().next().map_or(false, |c| c.is_ascii_digit());
            if run>=2 || (prev_digit && next_digit) { out.push('_'); }
        }
        let subwords = split_subwords(seg);
        for (j,w) in subwords.iter().enumerate() {
            let preserve = lead==1 && i==0 && j==0;
            out.push_str(&pascal_word(w, preserve));
        }
    }
    if trail>0 { out.push('_'); }
    out
