    if value==0 { return "0".to_string(); }
    let digits = if value <= 0xff {2} else if value <= 0xffff {4} else if value <= 0xffff_ffff {8} else {16};
    let raw = format!("{:0digits$x}", value, digits=digits);
    // insert underscores every 4 from right
    let mut out = String::from("0x");
    for (i,ch) in raw.chars().enumerate() {
        if i>0 && (raw.len()-i)%4==0 { out.push('_'); }
        out.push(ch);
    }
    out
}
pub fn hex_literal(value: u64) -> Literal {
    Literal::from_str(&hex_str(value)).unwrap()
}
pub fn hex_literal_usize(value: usize) -> Literal { hex_literal(value as u64) }

// Offset formatting in docs: 0x{:02x}
pub fn offset_str(value: u64) -> String { format!("0x{:02x}", value) }

pub fn escape_brackets(s:&str) -> String { s.replace('[', "\\[").replace(']', "\\]") }
