{"command":"cat > src/main.rs <<'RS'
mod config;
mod generate;
mod svd;
mod util;
mod xml;

use anyhow::Context;
use config::{Config, SourceType, Target};
use std::fs::File;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            // If logger was not yet initialized, initialize a fallback one from env.
            let _ = env_logger::Builder::from_env(env_logger::Env::default())
                .format_timestamp(None)
                .try_init();
            log::error!("{:?}", e);
            ExitCode::FAILURE
        }
    }
}

fn setup_logger(config: &Config) {
    let mut builder = env_logger::Builder::from_env(env_logger::Env::default());
    builder.format_timestamp(None);
    if std::env::var_os("RUST_LOG").is_none() {
        let level = config.log_level.as_deref().unwrap_or("info");
        builder.filter_level(level.parse().unwrap());
    }
    let _ = builder.try_init();
}

fn run() -> anyhow::Result<()> {
    let matches = config::build_command().get_matches();
    let mut config = Config::from_matches(&matches)?;
    setup_logger(&config);
    log::debug!("Current svd2rust config: {:#?}", config);

    // Read input first
    let (input_text, source_type) = if let Some(input_path) = &config.input {
        let mut file = File::open(input_path).context("Cannot open the SVD file")?;
        let mut text = String::new();
        file.read_to_string(&mut text).context("Cannot read the SVD file")?;
        let ext = input_path.extension().and_then(|s| s.to_str()).unwrap_or("");
        let st = match ext {
            "json" => SourceType::Json,
            "yaml" | "yml" => SourceType::Yaml,
            _ => SourceType::Xml,
        };
        (text, st)
    } else {
        let mut text = String::new();
        std::io::stdin().read_to_string(&mut text).context("Cannot read from stdin")?;
        (text, config.source_type)
    };

    // Settings file
    if let Some(settings_path) = &config.settings_file {
        let content = std::fs::read_to_string(settings_path).context("could not read settings file")?;
        // serde_yaml on empty returns error for struct; original accepts empty.
        let settings: config::Settings = if content.trim().is_empty() {
            config::Settings::default()
        } else {
            // serde_yaml may return None for "null" documents: handle via Option
            let opt: Option<config::Settings> = serde_yaml::from_str(&content).context("could not parse settings file")?;
            opt.unwrap_or_default()
        };
        if settings.html_url.is_some() { config.settings.html_url = settings.html_url; }
        if settings.crate_path.is_some() { config.settings.crate_path = settings.crate_path; }
        if settings.riscv_config.is_some() { config.settings.riscv_config = settings.riscv_config; }
    }

    log::info!("Parsing device from SVD file");
    let mut device = match source_type {
        SourceType::Xml => {
            let root = xml::parse_document(&input_text).map_err(|e| anyhow::anyhow!(e)).context("Error parsing SVD XML file")?;
            svd::parse_device_xml(&root, config.strict).context("Error parsing SVD XML file")?
        }
        SourceType::Json => {
            let dev: svd::Device = serde_json::from_str(&input_text).map_err(anyhow::Error::from).context("Error parsing SVD JSON file")?;
            svd::validate_device_json(&dev)?;
            dev
        }
        SourceType::Yaml => {
            let dev: svd::Device = serde_yaml::from_str(&input_text).map_err(anyhow::Error::from).context("Error parsing SVD YAML file")?;
            svd::validate_device_json(&dev)?;
            dev
        }
    };
    if config.base_address_shift != 0 {
        for p in &mut device.peripherals {
            p.base_address = p.base_address.wrapping_add(config.base_address_shift);
        }
    }

    log::info!("Rendering device");
    let output = generate::device::render(&device, &config).context("Error rendering device")?;

    let out_dir = config.output_dir.clone().unwrap_or_else(|| PathBuf::from(""));
    let lib_name = if config.make_mod { "mod.rs" } else { "lib.rs" };
    let lib_path = out_dir.join(lib_name);
    let mut lib_file = File::create(&lib_path).expect("Couldn't create output file");
    let lib_str = output.lib.to_string().replace(" # [", "\n#[");
    write!(lib_file, "{}", lib_str).expect("Couldn't write to output file");

    if let Some(device_x) = &output.device_x {
        let mut f = File::create(out_dir.join("device.x"))?;
        writeln!(f, "{}", device_x)?;
    }
    if let Some(build_rs) = &output.build_rs {
        let mut f = File::create(out_dir.join("build.rs"))?;
        writeln!(f, "{}", build_rs.to_string())?;
    }
    Ok(())
}
RS"}

