cat > src/generate/interrupt.rs <<'RS'
use crate::config::{Config, Edition, Target};
use crate::svd::Device;
use crate::util;
use proc_macro2::TokenStream;
use quote::quote;
use std::collections::BTreeMap;

pub struct InterruptInfo {
    pub name: String, // formatted ident string
    pub ident: proc_macro2::Ident,
    pub value: u32,
    pub desc: String,
}
pub fn collect(device: &Device, config: &Config) -> Vec<InterruptInfo> {
    let mut map: BTreeMap<u32, InterruptInfo> = BTreeMap::new();
    for p in &device.peripherals {
        for i in &p.interrupts {
            let desc = i.description.as_deref().map(util::clean_description).filter(|s| !s.is_empty()).unwrap_or_else(|| i.name.clone());
            // Note: if description present but cleaned empty, original behavior unknown; fallback above may differ.
            let info = InterruptInfo { name: util::ident_str(&i.name, config, "interrupt"), ident: util::ident(&i.name, config, "interrupt"), value: i.value, desc };
            map.insert(i.value, info);
        }
    }
    map.into_values().collect()
}
pub fn device_x(interrupts: &[InterruptInfo]) -> String {
    let mut s = String::new();
    for i in interrupts { s.push_str(&format!("PROVIDE({} = DefaultHandler);\n", i.name)); }
    s
}

fn enum_tokens(interrupts: &[InterruptInfo], config: &Config, doc_str: &str) -> TokenStream {
    let variants = interrupts.iter().map(|i| {
        let name = &i.ident;
        let val = proc_macro2::Literal::u32_unsuffixed(i.value);
        let doc = format!("{} - {}", i.value, i.desc);
        quote! { #[doc = #doc] #name = #val, }
    });
    let defmt = match &config.impl_defmt { Some(f) => quote! { #[cfg_attr(feature = #f, derive(defmt::Format))] }, None => quote!{} };
    if interrupts.is_empty() {
        quote! {
            #[doc = #doc_str]
            #defmt
            #[derive(Copy, Clone, Debug, PartialEq, Eq)]
            pub enum Interrupt {}
        }
    } else {
        quote! {
            #[doc = #doc_str]
            #defmt
            #[derive(Copy, Clone, Debug, PartialEq, Eq)]
            #[repr(u16)]
            pub enum Interrupt { #(#variants)* }
        }
    }
}
// The doc attributes in original for enum are r"..." raw strings because they were written as doc comments in quote.
// Using #[doc = #doc_str] with a String produces normal string, which would differ ("..." vs r"...").
// Therefore callers should use quote with raw doc via this helper that builds tokens manually? For now enum_tokens above returns normal; we instead implement render using raw literal construction below.
fn raw_doc_attr(text: &str) -> TokenStream {
    // Build #[doc = r"..."] token stream parsing; text may contain quotes -> use Literal::string fallback? For our static texts it's safe.
    // Use syn parse of code string would need escaping. Instead create tokens via quote with a raw string literal token parsed from source using proc_macro2 Literal.
    // proc_macro2::Literal::string produces "..."; we need r"...". Construct by parsing a token stream containing raw string.
    let raw = if !text.contains('"') { format!("r\"{}\"", text) } else if !text.contains("\"#") { format!("r#\"{}\"#", text) } else { return quote!{ #[doc = #text] }; };
    let lit: proc_macro2::Literal = raw.parse().unwrap();
    quote! { #[doc = #lit] }
}

fn enum_tokens2(interrupts: &[InterruptInfo], config: &Config, doc_text: &'static str) -> TokenStream {
    let doc = raw_doc_attr(doc_text);
    let variants = interrupts.iter().map(|i| {
        let name = &i.ident;
        let val = proc_macro2::Literal::u32_unsuffixed(i.value);
        let d = format!("{} - {}", i.value, i.desc);
        quote! { #[doc = #d] #name = #val, }
    });
    let defmt = match &config.impl_defmt { Some(f) => quote! { #[cfg_attr(feature = #f, derive(defmt::Format))] }, None => quote!{} };
    if interrupts.is_empty() {
        quote! { #doc #defmt #[derive(Copy, Clone, Debug, PartialEq, Eq)] pub enum Interrupt {} }
    } else {
        quote! { #doc #defmt #[derive(Copy, Clone, Debug, PartialEq, Eq)] #[repr(u16)] pub enum Interrupt { #(#variants)* } }
    }
}

fn try_from_tokens(interrupts: &[InterruptInfo], ty: TokenStream) -> TokenStream {
    let arms = interrupts.iter().map(|i| {
        let name=&i.ident; let val=proc_macro2::Literal::u32_unsuffixed(i.value);
        quote! { #val => Ok(Interrupt::#name), }
    });
    quote! {
        #[doc = r" TryFromInterruptError"]
        #[derive(Debug, Copy, Clone)]
        pub struct TryFromInterruptError(());
        impl Interrupt {
            #[doc = r" Attempt to convert a given value into an `Interrupt`"]
            #[inline]
            pub fn try_from(value: #ty) -> Result<Self, TryFromInterruptError> {
                match value { #(#arms)* _ => Err(TryFromInterruptError(())), }
            }
        }
    }
}

pub fn render(device: &Device, config: &Config, interrupts: &[InterruptInfo]) -> TokenStream {
    let _ = device;
    let is_2024 = matches!(config.edition, Edition::E2024);
    let max = interrupts.iter().map(|i| i.value).max();
    let len_lit = proc_macro2::Literal::usize_unsuffixed(max.map(|m| m as usize + 1).unwrap_or(0));
    let handlers: Vec<&proc_macro2::Ident> = interrupts.iter().map(|i| &i.ident).collect();
    // vector entries
    let mut entries: Vec<TokenStream> = Vec::new();
    if let Some(mx)=max {
        for idx in 0..=mx {
            if let Some(info)=interrupts.iter().find(|i| i.value==idx) {
                let h=&info.ident; entries.push(quote!{ Vector { _handler: #h }, });
            } else { entries.push(quote!{ Vector { _reserved: 0 }, }); }
        }
    }
    match config.target {
        Target::CortexM => {
            let link_section = config.interrupt_link_section.as_deref().unwrap_or(".vector_table.interrupts");
            let extern_block = if is_2024 { quote!{ #[cfg(feature = "rt")] unsafe extern "C" { #(fn #handlers();)* } } } else { quote!{ #[cfg(feature = "rt")] extern "C" { #(fn #handlers();)* } } };
            let static_attrs = if is_2024 { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[unsafe(link_section = #link_section)] #[unsafe(no_mangle)] } } else { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[link_section = #link_section] #[no_mangle] } };
            let enum_ts = enum_tokens2(interrupts, config, "Enumeration of all the interrupts.");
            let number_body = if interrupts.is_empty() { quote!{ match self {} } } else { quote!{ self as u16 } };
            quote! {
                #extern_block
                #[doc(hidden)]
                #[repr(C)]
                pub union Vector { _handler: unsafe extern "C" fn(), _reserved: u32 }
                #static_attrs
                pub static __INTERRUPTS: [Vector; #len_lit] = [#(#entries)*];
                #enum_ts
                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 { #number_body }
                }
            }
        }
        Target::Msp430 => {
            let link_section = config.interrupt_link_section.as_deref().unwrap_or(".vector_table.interrupts");
            let (extern_block, static_attrs) = if is_2024 {
                (quote!{ #[cfg(feature="rt")] unsafe extern "msp430-interrupt" { #(fn #handlers();)* } }, quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[unsafe(link_section=#link_section)] #[unsafe(no_mangle)] #[used] })
            } else {
                (quote!{ #[cfg(feature="rt")] extern "msp430-interrupt" { #(fn #handlers();)* } }, quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[link_section=#link_section] #[no_mangle] #[used] })
            };
            let enum_ts = enum_tokens2(interrupts, config, "Enumeration of all the interrupts. This enum is seldom used in application or library crates. It is present primarily for documenting the device's implemented interrupts.");
            quote!{
                #extern_block
                #[doc(hidden)] #[repr(C)] pub union Vector { _handler: unsafe extern "msp430-interrupt" fn(), _reserved: u16 }
                #static_attrs pub static __INTERRUPTS: [Vector; #len_lit] = [#(#entries)*];
                #enum_ts
            }
        }
        Target::XtensaLX => {
            let extern_block = if is_2024 { quote!{ #[cfg(feature="rt")] unsafe extern "C" { #(fn #handlers();)* } } } else { quote!{ #[cfg(feature="rt")] extern "C" { #(fn #handlers();)* } } };
            let static_attr = if is_2024 { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[unsafe(no_mangle)] } } else { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[no_mangle] } };
            let enum_ts = enum_tokens2(interrupts, config, "Enumeration of all the interrupts.");
            let tryf = try_from_tokens(interrupts, quote!{u16});
            quote!{
                #extern_block
                #[doc(hidden)] #[repr(C)] pub union Vector { pub _handler: unsafe extern "C" fn(), _reserved: u32 }
                #static_attr pub static __INTERRUPTS: [Vector; #len_lit] = [#(#entries)*];
                #enum_ts
                #tryf
            }
        }
        Target::RISCV => {
            if config.settings.riscv_config.is_some() {
                crate::generate::device::render_riscv_new(device, config, interrupts)
            } else {
                // legacy - warnings logged in device.rs
                let extern_block = if is_2024 { quote!{ #[cfg(feature="rt")] unsafe extern "C" { #(fn #handlers();)* } } } else { quote!{ #[cfg(feature="rt")] extern "C" { #(fn #handlers();)* } } };
                let static_attr = if is_2024 { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[unsafe(no_mangle)] } } else { quote!{ #[cfg(feature="rt")] #[doc(hidden)] #[no_mangle] } };
                let base = quote!{
                    #extern_block
                    #[doc(hidden)] #[repr(C)] pub union Vector { pub _handler: unsafe extern "C" fn(), pub _reserved: usize }
                    #static_attr pub static __EXTERNAL_INTERRUPTS: [Vector; #len_lit] = [#(#entries)*];
                };
                if interrupts.is_empty() { return base; }
                let enum_ts = enum_tokens2(interrupts, config, "Enumeration of all the interrupts.");
                let tryf = try_from_tokens(interrupts, quote!{u8});
                // interrupt macro written as doc comments in quote to preserve raw docs
                quote!{
                    #base
                    #[doc(hidden)]
                    pub mod interrupt {
                        #enum_ts
                        #tryf
                        #[cfg(feature = "rt")]
                        #[macro_export]
                        /// Assigns a handler to an interrupt
                        ///
                        /// This macro takes two arguments: the name of an interrupt and the path to the
                        /// function that will be used as the handler of that interrupt. That function
                        /// must have signature `fn()`.
                        ///
                        /// Optionally, a third argument may be used to declare interrupt local data.
                        /// The handler will have exclusive access to these *local* variables on each
                        /// invocation. If the third argument is used then the signature of the handler
                        /// function must be `fn(&mut $NAME::Locals)` where `$NAME` is the first argument
                        /// passed to the macro.
                        ///
                        /// # Example
                        ///
                        /// ``` ignore
                        /// interrupt!(TIM2, periodic);
                        ///
                        /// fn periodic() {
                        ///     print!(".");
                        /// }
                        ///
                        /// interrupt!(TIM3, tick, locals: {
                        ///     tick: bool = false;
                        /// });
                        ///
                        /// fn tick(locals: &mut TIM3::Locals) {
                        ///     locals.tick = !locals.tick;
                        ///
                        ///     if locals.tick {
                        ///         println!("Tick");
                        ///     } else {
                        ///         println!("Tock");
                        ///     }
                        /// }
                        /// ```
                        macro_rules! interrupt {
                            ($NAME:ident, $path:path, locals: { $($lvar:ident: $lty:ty = $lval:expr;)* }) => {
                                #[allow(non_snake_case)]
                                mod $NAME { pub struct Locals { $(pub $lvar: $lty,)* } }
                                #[allow(non_snake_case)]
                                #[no_mangle]
                                pub extern "C" fn $NAME() {
                                    let _ = $crate::interrupt::Interrupt::$NAME;
                                    static mut LOCALS: self::$NAME::Locals = self::$NAME::Locals { $($lvar: $lval,)* };
                                    let f: fn(&mut self::$NAME::Locals) = $path;
                                    f(unsafe { &mut LOCALS });
                                }
                            };
                            ($NAME:ident, $path:path) => {
                                #[allow(non_snake_case)]
                                #[no_mangle]
                                pub extern "C" fn $NAME() {
                                    let _ = $crate::interrupt::Interrupt::$NAME;
                                    let f: fn() = $path;
                                    f();
                                }
                            }
                        }
                    }
                    pub use self::interrupt::Interrupt;
                }
            }
        }
        Target::Mips | Target::None => {
            if interrupts.is_empty() { return quote!{}; }
            let enum_ts = enum_tokens2(interrupts, config, "Enumeration of all the interrupts.");
            let tryf = try_from_tokens(interrupts, quote!{u8});
            quote!{
                #[doc(hidden)]
                pub mod interrupt {
                    #enum_ts
                    #tryf
                }
                pub use self::interrupt::Interrupt;
            }
        }
    }
}
