pub fn bits_to_ty(bits: u32) -> anyhow::Result<Ident> {
    let name = match bits { 0..=8=>"u8", 9..=16=>"u16", 17..=32=>"u32", 33..=64=>"u64", _=>return Err(anyhow!("can't convert {} bits into a Rust integral type", bits)) };
