fn access_abbr(a: Access) -> &'static str { match a { Access::ReadOnly=>"r", Access::WriteOnly|Access::WriteOnce=>"w", Access::ReadWrite|Access::ReadWriteOnce=>"rw" } }

pub fn spec_doc(desc: &str, mod_name: &str, readable: bool, writable: bool, can_reset: bool, can_write: bool, html: Option<&str>) -> String {
