#[derive(Clone)]
struct FieldCtx {
    field: FieldInfo,
    can_read: bool,
    can_write: bool,
    // expanded field instances for dim: (expanded_name, offset)
    instances: Vec<(String,u32)>,
}

fn field_mask(offset:u32, width:u32, reg_bits:u32) -> u128 {
    // mask in field position for reader expression uses only width mask after shifting
    let _=(offset,reg_bits);
    if width>=128 { u128::MAX } else { (1u128<<width)-1 }
}

fn enum_base_name(field:&FieldInfo, ev:&EnumeratedValues, config:&Config) -> String {
    if !config.field_names_for_enums {
        if let Some(n)=&ev.name { return n.clone(); }
    }
    field.name.clone()
}

#[derive(Clone)]
struct EnumInfo {
    ident: Ident,
    variants: Vec<VariantInfo>,
    is_bool: bool,
    ux: Ident, // for non bool
    complete: bool, // covers all values or has default
    default_variant: Option<usize>,
}
#[derive(Clone)]
struct VariantInfo { ident: Ident, accessor_is: Ident, accessor: Ident, value: u64, doc: String, is_default: bool }

fn build_enum_info(field:&FieldInfo, ev:&EnumeratedValues, name_ident: Ident, reg_props:&ResolvedProps) -> EnumInfo {
    let is_bool = field.bit_width==1;
    let ux = bits_to_ty(field.bit_width).unwrap_or_else(|_| util::ident_raw("u64"));
    // assign values to default variants: choose smallest unused non-negative integer? Based probe.
    let mut used: Vec<u64> = ev.values.iter().filter_map(|v| v.value).collect();
    let mut variants=Vec::new(); let mut default_idx=None;
    for (idx,v) in ev.values.iter().enumerate() {
        let is_def = v.is_default.unwrap_or(false);
        let value = if let Some(val)=v.value { val } else {
            // Find first unused
            let mut candidate=0u64; while used.contains(&candidate) { candidate+=1; } used.push(candidate); candidate
        };
        if is_def { default_idx=Some(idx); }
        let vdoc = v.description.as_deref().map(util::clean_description).unwrap_or_default();
        // accessor names use enum_value / enum_value_accessor formats on variant name
        variants.push(VariantInfo{
            ident: util::ident(&v.name, unsafe { CONFIG_PTR }, "enum_value"),
            accessor_is: util::ident_raw(&format!("is_{}", util::ident_str(&v.name, unsafe{CONFIG_PTR}, "enum_value_accessor"))),
            accessor: util::ident(&v.name, unsafe{CONFIG_PTR}, "enum_value_accessor"),
            value, doc: vdoc, is_default:is_def
        });
    }
    let total: u128 = if field.bit_width>=64 { u128::MAX } else { 1u128<<field.bit_width };
    let mut uniq = variants.iter().map(|v| v.value as u128).collect::<Vec<_>>(); uniq.sort(); uniq.dedup();
    let complete = default_idx.is_some() || (uniq.len() as u128 >= total);
    let _=reg_props;
    EnumInfo{ ident:name_ident, variants, is_bool, ux, complete, default_variant:default_idx }
}
// Global config pointer workaround to avoid threading config into enum builder signature in this draft – set in render()
static mut CONFIG_PTR: &Config = unsafe { &*std::ptr::null::<Config>() };
// Instead of global hack (unsafe), we'll set via thread_local in render and change functions later if needed.

fn render_enum(field:&FieldInfo, ev:&EnumeratedValues, info:&EnumInfo, config:&Config, reg_props:&ResolvedProps, usage_write:bool) -> TokenStream {
    let enum_ident=&info.ident;
    let field_desc = util::description_or_empty(field.description.as_deref());
    let doc = if let Some(rv)=reg_props.reset_value {
        let reset_field = if field.bit_offset>=64 {0} else { (rv>>field.bit_offset) & (if field.bit_width>=64 {u64::MAX} else {(1u64<<field.bit_width)-1}) };
        format!("{}\n\nValue on reset: {}", field_desc, reset_field)
    } else { field_desc.clone() };
    let variants = info.variants.iter().map(|v| {
        let id=&v.ident; let val=Literal::u64_unsuffixed(v.value); let d=format!("{}: {}", v.value, v.doc);
        quote!{ #[doc=#d] #id = #val, }
    });
    let defmt = match &config.impl_defmt { Some(f)=>quote!{ #[cfg_attr(feature=#f, derive(defmt::Format))] }, None=>quote!{} };
    if info.is_bool {
        quote!{
            #[doc=#doc]
            #defmt
            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
            pub enum #enum_ident { #(#variants)* }
            impl From<#enum_ident> for bool { #[inline(always)] fn from(variant: #enum_ident) -> Self { variant as u8 != 0 } }
        }
    } else {
        let ux=&info.ux;
        quote!{
            #[doc=#doc]
            #defmt
            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
            #[repr(#ux)]
            pub enum #enum_ident { #(#variants)* }
            impl From<#enum_ident> for #ux { #[inline(always)] fn from(variant: #enum_ident) -> Self { variant as _ } }
            impl crate::FieldSpec for #enum_ident { type Ux = #ux; }
            impl crate::IsEnum for #enum_ident {}
        }
    }
}

