    let desc2 = match &reg.description { Some(d)=>util::clean_description(d), None=>{ log::warn!("Missing description for register {}", reg.name); String::new() } };
    let spec_doc_str = spec_doc(&desc2, &mod_str, readable, writable, can_reset, can_write_doc, html_url.as_deref());
    // R/W type aliases and impls
    let r_alias = if readable { let d=format!("Register `{}` reader", reg.name); quote!{ #[doc=#d] pub type R = crate::R<#reg_spec>; } } else { quote!{} };
    let w_alias = if writable { let d=format!("Register `{}` writer", reg.name); quote!{ #[doc=#d] pub type W = crate::W<#reg_spec>; } } else { quote!{} };
    let r_impl = if readable {
        if any_readable_fields {
            let debug_impl = if config.impl_debug {
                let field_calls = field_ctxs.iter().filter(|fc| fc.can_read).flat_map(|fc| fc.instances.iter().map(move |(inst_name,_)| {
                    let acc=util::ident(inst_name, config, "field_accessor"); let acc_str=acc.to_string();
                    quote!{ .field(#acc_str, &self.#acc()) }
                }));
                let cfg_attr = match &config.impl_debug_feature { Some(f)=>quote!{ #[cfg(feature=#f)] }, None=>quote!{} };
                let reg_name=&reg.name;
                quote!{ #cfg_attr impl core::fmt::Debug for R { fn fmt(&self, f:&mut core::fmt::Formatter) -> core::fmt::Result { f.debug_struct(#reg_name) #(#field_calls)* .finish() } } }
            } else { quote!{} };
            quote!{ impl R { #r_methods } #debug_impl }
        } else {
            // debug write bits (also when impl_debug? original with no fields likely same; with feature maybe gated? defer)
            if config.impl_debug {
                // Check original later; for now same but cfg gated if feature
                let cfg_attr = match &config.impl_debug_feature { Some(f)=>quote!{ #[cfg(feature=#f)] }, None=>quote!{} };
                quote!{ #cfg_attr impl core::fmt::Debug for R { fn fmt(&self, f:&mut core::fmt::Formatter) -> core::fmt::Result { write!(f, "{}", self.bits()) } } }
            } else {
                quote!{ impl core::fmt::Debug for R { fn fmt(&self, f:&mut core::fmt::Formatter) -> core::fmt::Result { write!(f, "{}", self.bits()) } } }
            }
        }
    } else { quote!{} };
    let w_impl = if writable { quote!{ impl W { #w_methods } } } else { quote!{} };
    // Writable impl
    let writable_impl = if writable {
        let safety = if register_safe { quote!{ crate::Safe } } else { quote!{ crate::Unsafe } };
        let mut consts=TokenStream::new();
        if zero_bitmap!=0 { let lit=util::hex_literal(zero_bitmap as u64); consts.extend(quote!{ const ZERO_TO_MODIFY_FIELDS_BITMAP: Self::Ux = #lit; }); }
        if one_bitmap!=0 { let lit=util::hex_literal(one_bitmap as u64); consts.extend(quote!{ const ONE_TO_MODIFY_FIELDS_BITMAP: Self::Ux = #lit; }); }
        let docw=format!("`write(|w| ..)` method takes [`{}::W`](W) writer structure", mod_str);
        quote!{ #[doc=#docw] impl crate::Writable for #reg_spec { type Safety = #safety; #consts } }
    } else { quote!{} };
    let readable_impl = if readable { let docr=format!("`read()` method returns [`{}::R`](R) reader structure", mod_str); quote!{ #[doc=#docr] impl crate::Readable for #reg_spec {} } } else { quote!{} };
    let reset_impl = if let Some(rv)=props.reset_value {
        let doc_reset = format!("`reset()` method sets {} to value {}", reg.name, util::hex_str(rv));
        if rv==0 { quote!{ #[doc=#doc_reset] impl crate::Resettable for #reg_spec {} } }
        else { let lit=util::hex_literal(rv); quote!{ #[doc=#doc_reset] impl crate::Resettable for #reg_spec { const RESET_VALUE: Self::Ux = #lit; } } }
    } else { quote!{} };
    let tokens = quote!{
        #[doc=#alias_doc_str]
        #alias_attr
        pub type #reg_ty = crate::Reg<#reg_mod::#reg_spec>;
        #[doc=#desc_clean]
        pub mod #reg_mod {
            #r_alias
            #w_alias
            #field_decls
            #r_impl
            #w_impl
            #[doc=#spec_doc_str]
            pub struct #reg_spec;
            impl crate::RegisterSpec for #reg_spec { type Ux = #ux; }
            #readable_impl
            #writable_impl
            #reset_impl
        }
    };
    Ok(RegisterRenderOut{tokens})
}

fn reader_expr(offset:u32, width:u32, reg_size:u32) -> TokenStream {
    let mask = field_mask(offset,width,reg_size);
    // mask literal: decimal as in original (1,3,etc) For larger masks, original uses decimal? Example width 8 mask 255 likely. Width 32 mask maybe 0xffffffff? Probe later.
    let mask_lit = Literal::from_str(&mask.to_string()).unwrap();
    if width==1 {
        if offset==0 { quote!{ (self.bits & #mask_lit) != 0 } } else { let o=Literal::u32_unsuffixed(offset); quote!{ ((self.bits >> #o) & #mask_lit) != 0 } }
    } else {
        let ty = bits_to_ty(width).unwrap();
        if offset==0 {
            // if width == reg_size, mask could be all bits; original maybe `self.bits` directly? defer
            quote!{ (self.bits & #mask_lit) as #ty }
        } else { let o=Literal::u32_unsuffixed(offset); quote!{ ((self.bits >> #o) & #mask_lit) as #ty } }
    }
}
use std::str::FromStr;

fn render_reader_impl_enum(reader_ty:&Ident, info:&EnumInfo, is_bool:bool) -> TokenStream {
    let eid=&info.ident;
    let is_methods = info.variants.iter().map(|v| {
        let is_name=&v.accessor_is; let vid=&v.ident; let d=&v.doc;
        if v.is_default {
            quote!{ #[doc=#d] #[inline(always)] pub fn #is_name(&self) -> bool { matches!(self.variant(), #eid::#vid) } }
        } else {
            quote!{ #[doc=#d] #[inline(always)] pub fn #is_name(&self) -> bool { *self == #eid::#vid } }
        }
    });
    if is_bool {
        if info.complete {
            let arms=info.variants.iter().map(|v| { let vid=&v.ident; if v.value==0 { quote!{ false => #eid::#vid, } } else { quote!{ true => #eid::#vid, } } });
            quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> #eid { match self.bits { #(#arms)* } } #(#is_methods)* } }
        } else {
            let arms=info.variants.iter().map(|v| { let vid=&v.ident; if v.is_default { quote!{ _ => #eid::#vid, } } else if v.value==0 { quote!{ false => Some(#eid::#vid), } } else { quote!{ true => Some(#eid::#vid), } } });
            // default handling for bool: if default, variant() returns enum not Option
            if info.default_variant.is_some() {
                // need arms without Some for non-default - rebuild: for simplicity use conditional compilation via separate arms
                let arms2=info.variants.iter().map(|v| { let vid=&v.ident; if v.is_default { quote!{ _ => #eid::#vid, } } else if v.value==0 { quote!{ false => #eid::#vid, } } else { quote!{ true => #eid::#vid, } } });
                return quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> #eid { match self.bits { #(#arms2)* } } #(#is_methods)* } };
            }
            quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> Option<#eid> { match self.bits { #(#arms)* _ => None, } } #(#is_methods)* } }
        }
    } else {
        if info.complete && info.default_variant.is_none() {
            let arms=info.variants.iter().map(|v| { let vid=&v.ident; let val=Literal::u64_unsuffixed(v.value); quote!{ #val => #eid::#vid, } });
            quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> #eid { match self.bits { #(#arms)* _ => unreachable!(), } } #(#is_methods)* } }
        } else if info.default_variant.is_some() {
            let arms=info.variants.iter().map(|v| { let vid=&v.ident; if v.is_default { quote!{ _ => #eid::#vid, } } else { let val=Literal::u64_unsuffixed(v.value); quote!{ #val => #eid::#vid, } } });
            quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> #eid { match self.bits { #(#arms)* } } #(#is_methods)* } }
        } else {
            let arms=info.variants.iter().map(|v| { let vid=&v.ident; let val=Literal::u64_unsuffixed(v.value); quote!{ #val => Some(#eid::#vid), } });
            quote!{ impl #reader_ty { #[doc="Get enumerated values variant"] #[inline(always)] pub const fn variant(&self) -> Option<#eid> { match self.bits { #(#arms)* _ => None, } } #(#is_methods)* } }
        }
    }
}
fn render_writer_impl_enum(writer_ty:&Ident, info:&EnumInfo, is_bool:bool, reg_ux:&Ident) -> TokenStream {
    let eid=&info.ident;
    let methods=info.variants.iter().map(|v| { let acc=&v.accessor; let vid=&v.ident; let d=&v.doc; quote!{ #[doc=#d] #[inline(always)] pub fn #acc(self) -> &'a mut crate::W<REG> { self.variant(#eid::#vid) } } });
    if is_bool {
        quote!{ impl<'a, REG> #writer_ty<'a, REG> where REG: crate::Writable + crate::RegisterSpec { #(#methods)* } }
    } else {
        let ux=&info.ux;
        quote!{ impl<'a, REG> #writer_ty<'a, REG> where REG: crate::Writable + crate::RegisterSpec, REG::Ux: From<#ux> { #(#methods)* } }
    }
}
