use crate::config::{Config};
use crate::svd::*;
use crate::util;
use anyhow::{anyhow, Context};
use proc_macro2::{Ident, Literal, TokenStream};
use quote::quote;

pub fn bits_to_ty(bits: u32) -> anyhow::Result<Ident> {
    let name = match bits { 0..=8=>"u8", 9..=16=>"u16", 17..=32=>"u32", 33..=64=>"u64", _=>return Err(anyhow!("can't convert {} bits into a Rust integral type", bits)) };
    Ok(util::ident_raw(name))
}
pub fn bits_to_bytes(bits: u32) -> u32 { bits.div_ceil(8) }

#[derive(Clone, Copy)]
pub struct ResolvedProps { pub size: u32, pub access: Access, pub reset_value: Option<u64>, pub reset_mask: Option<u64> }

pub fn resolve_props(reg: &RegisterInfo, defaults: &RegisterProperties) -> anyhow::Result<ResolvedProps> {
    let merged = reg.properties.merge(defaults);
    let size = match merged.size { Some(s)=>s, None=>return Err(anyhow!("Register {} has no `size` field", reg.name)) };
    Ok(ResolvedProps{ size, access: merged.access.unwrap_or(Access::ReadWrite), reset_value: merged.reset_value, reset_mask: merged.reset_mask })
}

fn access_abbr(a: Access) -> &'static str { match a { Access::ReadOnly=>"r", Access::WriteOnly|Access::WriteOnce=>"w", Access::ReadWrite|Access::ReadWriteOnce=>"rw" } }

pub fn spec_doc(desc: &str, mod_name: &str, readable: bool, writable: bool, can_reset: bool, can_write: bool, html: Option<&str>) -> String {
    // desc already cleaned
    let mut out = String::new();
    out.push_str(desc);
    out.push_str("\n\n");
    if readable { out.push_str(&format!("You can [`read`](crate::Reg::read) this register and get [`{}::R`](R). ", mod_name)); }
    if writable {
        let mut methods: Vec<String> = Vec::new();
        if can_reset { methods.push("[`reset`](crate::Reg::reset)".into()); }
        if can_write { methods.push("[`write`](crate::Reg::write)".into()); }
        methods.push("[`write_with_zero`](crate::Reg::write_with_zero)".into());
        out.push_str(&format!("You can {} this register using [`{}::W`](W). ", methods.join(", "), mod_name));
    }
    if readable && writable { out.push_str("You can also [`modify`](crate::Reg::modify) this register. "); }
    out.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");
    if let Some(h)=html { out.push_str(&format!("\n\nSee register [structure]({})", h)); }
    out
}
pub fn alias_doc(name: &str, abbr: &str, desc: &str, mod_name: &str, readable: bool, writable: bool, can_reset: bool, can_write: bool, html: Option<&str>) -> String {
    let mut out = format!("{} ({}) register accessor: {}\n\n", name, abbr, desc);
    if readable { out.push_str(&format!("You can [`read`](crate::Reg::read) this register and get [`{}::R`]. ", mod_name)); }
    if writable {
        let mut methods: Vec<String>=Vec::new();
        if can_reset { methods.push("[`reset`](crate::Reg::reset)".into()); }
        if can_write { methods.push("[`write`](crate::Reg::write)".into()); }
        methods.push("[`write_with_zero`](crate::Reg::write_with_zero)".into());
        out.push_str(&format!("You can {} this register using [`{}::W`]. ", methods.join(", "), mod_name));
    }
    if readable && writable { out.push_str("You can also [`modify`](crate::Reg::modify) this register. "); }
    out.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");
    if let Some(h)=html { out.push_str(&format!("\n\nSee register [structure]({})", h)); }
    out.push_str(&format!("\n\nFor information about available fields see [`mod@{}`] module", mod_name));
    out
}

#[derive(Clone)]
struct FieldCtx {
    field: FieldInfo,
    can_read: bool,
    can_write: bool,
    // expanded field instances for dim: (expanded_name, offset)
    instances: Vec<(String,u32)>,
}

fn field_mask(offset:u32, width:u32, reg_bits:u32) -> u128 {
    // mask in field position for reader expression uses only width mask after shifting
    let _=(offset,reg_bits);
    if width>=128 { u128::MAX } else { (1u128<<width)-1 }
}

fn enum_base_name(field:&FieldInfo, ev:&EnumeratedValues, config:&Config) -> String {
    if !config.field_names_for_enums {
        if let Some(n)=&ev.name { return n.clone(); }
    }
    field.name.clone()
}

#[derive(Clone)]
struct EnumInfo {
    ident: Ident,
    variants: Vec<VariantInfo>,
    is_bool: bool,
    ux: Ident, // for non bool
    complete: bool, // covers all values or has default
    default_variant: Option<usize>,
}
#[derive(Clone)]
struct VariantInfo { ident: Ident, accessor_is: Ident, accessor: Ident, value: u64, doc: String, is_default: bool }

fn build_enum_info(field:&FieldInfo, ev:&EnumeratedValues, name_ident: Ident, reg_props:&ResolvedProps) -> EnumInfo {
    let is_bool = field.bit_width==1;
    let ux = bits_to_ty(field.bit_width).unwrap_or_else(|_| util::ident_raw("u64"));
    // assign values to default variants: choose smallest unused non-negative integer? Based probe.
    let mut used: Vec<u64> = ev.values.iter().filter_map(|v| v.value).collect();
    let mut variants=Vec::new(); let mut default_idx=None;
    for (idx,v) in ev.values.iter().enumerate() {
        let is_def = v.is_default.unwrap_or(false);
        let value = if let Some(val)=v.value { val } else {
            // Find first unused
            let mut candidate=0u64; while used.contains(&candidate) { candidate+=1; } used.push(candidate); candidate
        };
        if is_def { default_idx=Some(idx); }
        let vdoc = v.description.as_deref().map(util::clean_description).unwrap_or_default();
        // accessor names use enum_value / enum_value_accessor formats on variant name
        variants.push(VariantInfo{
            ident: util::ident(&v.name, unsafe { CONFIG_PTR }, "enum_value"),
            accessor_is: util::ident_raw(&format!("is_{}", util::ident_str(&v.name, unsafe{CONFIG_PTR}, "enum_value_accessor"))),
            accessor: util::ident(&v.name, unsafe{CONFIG_PTR}, "enum_value_accessor"),
            value, doc: vdoc, is_default:is_def
        });
    }
    let total: u128 = if field.bit_width>=64 { u128::MAX } else { 1u128<<field.bit_width };
    let mut uniq = variants.iter().map(|v| v.value as u128).collect::<Vec<_>>(); uniq.sort(); uniq.dedup();
    let complete = default_idx.is_some() || (uniq.len() as u128 >= total);
    let _=reg_props;
    EnumInfo{ ident:name_ident, variants, is_bool, ux, complete, default_variant:default_idx }
}
// Global config pointer workaround to avoid threading config into enum builder signature in this draft – set in render()
static mut CONFIG_PTR: &Config = unsafe { &*std::ptr::null::<Config>() };
// Instead of global hack (unsafe), we'll set via thread_local in render and change functions later if needed.

fn render_enum(field:&FieldInfo, ev:&EnumeratedValues, info:&EnumInfo, config:&Config, reg_props:&ResolvedProps, usage_write:bool) -> TokenStream {
    let enum_ident=&info.ident;
    let field_desc = util::description_or_empty(field.description.as_deref());
    let doc = if let Some(rv)=reg_props.reset_value {
        let reset_field = if field.bit_offset>=64 {0} else { (rv>>field.bit_offset) & (if field.bit_width>=64 {u64::MAX} else {(1u64<<field.bit_width)-1}) };
        format!("{}\n\nValue on reset: {}", field_desc, reset_field)
    } else { field_desc.clone() };
    let variants = info.variants.iter().map(|v| {
        let id=&v.ident; let val=Literal::u64_unsuffixed(v.value); let d=format!("{}: {}", v.value, v.doc);
        quote!{ #[doc=#d] #id = #val, }
    });
    let defmt = match &config.impl_defmt { Some(f)=>quote!{ #[cfg_attr(feature=#f, derive(defmt::Format))] }, None=>quote!{} };
    if info.is_bool {
        quote!{
            #[doc=#doc]
            #defmt
            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
            pub enum #enum_ident { #(#variants)* }
            impl From<#enum_ident> for bool { #[inline(always)] fn from(variant: #enum_ident) -> Self { variant as u8 != 0 } }
        }
    } else {
        let ux=&info.ux;
        quote!{
            #[doc=#doc]
            #defmt
            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
            #[repr(#ux)]
            pub enum #enum_ident { #(#variants)* }
            impl From<#enum_ident> for #ux { #[inline(always)] fn from(variant: #enum_ident) -> Self { variant as _ } }
            impl crate::FieldSpec for #enum_ident { type Ux = #ux; }
            impl crate::IsEnum for #enum_ident {}
        }
    }
}

pub struct RegisterRenderOut { pub tokens: TokenStream }

pub fn render(reg:&RegisterInfo, name_for_type:&str, defaults:&RegisterProperties, config:&Config, path:&str, html_url: Option<String>) -> anyhow::Result<RegisterRenderOut> {
    // set global for enum builder (single-threaded)
    unsafe { CONFIG_PTR = config; }
    let props = resolve_props(reg, defaults).with_context(|| format!("can't render register '{}'", reg.name))?;
    // wrap other errors in can't render register at caller? Actual errors inside like size are already within; field access error should be directly Err returned and caller in peripheral adds context? Observed chain: can't render peripheral -> can't render register -> Field ... So render() errors should be returned bare and peripheral will context can't render register? But for size, resolve_props error is bare "Register R has no size" then caller peripheral contexts. We'll return bare errors and let peripheral add register context except our resolve above already added - remove:
    // (Handled by caller rework: peripheral will not duplicate if we keep this; to match, we keep context here and peripheral only adds peripheral context.)
    let readable = props.access.can_read();
    let writable = props.access.can_write();
    let desc_clean = match &reg.description {
        Some(d)=>util::clean_description(d),
        None=>{ log::warn!("Missing description for register {}", reg.name); String::new() }
    };
    // Second warning generation happens because description is fetched a second time in original for spec doc. Emulate: if missing, warn again when building spec doc below (we will log again there)
    let reg_ty = util::ident(name_for_type, config, "register");
    let reg_mod = util::ident(name_for_type, config, "register_mod");
    let reg_spec = util::ident(name_for_type, config, "register_spec");
    let mod_str = reg_mod.to_string();
    let ux = bits_to_ty(props.size).map_err(|e| e)?; // message bare, peripheral will add? We'll let main peripheral context add can't render register around render call, so keep bare here (but resolve_props above adds; inconsistent revisit)
    let can_reset = props.reset_value.is_some();
    // can_write for doc (the `write` method) requires Resettable in generic API; observed no-reset doc omitted write but kept write_with_zero.
    let can_write_doc = can_reset;
    let alias_doc_str = alias_doc(name_for_type, access_abbr(props.access), &desc_clean, &mod_str, readable, writable, can_reset, can_write_doc, html_url.as_deref());
    let alias_attr = if util::ident_str(name_for_type, config, "register") != name_for_type {
        let alias_name = name_for_type;
        quote!{ #[doc(alias = #alias_name)] }
    } else { quote!{} };
    // Build fields
    let mut field_ctxs: Vec<FieldCtx> = Vec::new();
    if let Some(fields)=&reg.fields {
        for f in fields {
            let fa = f.access.unwrap_or(props.access);
            let cr = readable && fa.can_read();
            let cw = writable && fa.can_write();
            if !cr && !cw {
                return Err(anyhow!("Field {}.{}.{} is not writtable or readable", path, reg.name, f.name));
            }
            // dim expansion for field instances
            let mut instances=Vec::new();
            if let Some(dim)=f.dim.dim {
                let indices=f.dim.indices().unwrap_or_default();
                let incr=f.dim.dim_increment.unwrap_or(f.bit_width);
                for (i,idx) in indices.iter().enumerate() {
                    let exp_name = f.name.replace("[%s]", idx).replace("%s", idx);
                    instances.push((exp_name, f.bit_offset + (i as u32)*incr));
                }
                let _=dim;
            } else { instances.push((f.name.clone(), f.bit_offset)); }
            field_ctxs.push(FieldCtx{field:f.clone(), can_read:cr, can_write:cw, instances});
        }
    }
    // Tokens inside mod: field enum/type declarations
    let mut field_decls = TokenStream::new();
    let mut r_methods = TokenStream::new();
    let mut w_methods = TokenStream::new();
    let mut any_readable_fields=false;
    let mut any_writable_fields=false;
    // Safety analysis
    let mut register_safe = writable; // will refine
    if field_ctxs.is_empty() { register_safe=false; }
    // bitmaps
    let mut zero_bitmap: u128=0; let mut one_bitmap: u128=0;
    for fc in &field_ctxs {
        let f=&fc.field;
        if fc.can_read { any_readable_fields=true; }
        if fc.can_write { any_writable_fields=true; }
        // modified write values bitmaps computed per field instance? register level mwv applies to all fields' bits
        let mwv = f.modified_write_values.or(reg.modified_write_values);
        for (_,off) in &fc.instances {
            let mask = field_mask(*off,f.bit_width,props.size) << (*off);
            match mwv {
                Some(ModifiedWriteValues::OneToClear)|Some(ModifiedWriteValues::OneToSet)|Some(ModifiedWriteValues::OneToToggle) => { one_bitmap |= mask; }
                Some(ModifiedWriteValues::ZeroToClear)|Some(ModifiedWriteValues::ZeroToSet)|Some(ModifiedWriteValues::ZeroToToggle) => { zero_bitmap |= mask; }
                _=>{}
            }
        }
        // Determine enums for read/write
        let mut read_ev: Option<&EnumeratedValues>=None;
        let mut write_ev: Option<&EnumeratedValues>=None;
        for ev in &f.enumerated_values {
            match ev.usage { Some(Usage::Read)=>{ read_ev=Some(ev); }, Some(Usage::Write)=>{ write_ev=Some(ev); }, Some(Usage::ReadWrite)|None=>{ read_ev=Some(ev); write_ev=Some(ev); } }
        }
        // If field cannot read/write respectively, ignore that side
        if !fc.can_read { read_ev=None; }
        if !fc.can_write { write_ev=None; }
        let same_ev = match (read_ev,write_ev) { (Some(r),Some(w))=>std::ptr::eq(r,w), _=>false };
        // We'll generate enum infos and decls plus type alias
        let field_reader_ty = util::ident(&f.name, config, "field_reader");
        let field_writer_ty = util::ident(&f.name, config, "field_writer");
        let fdesc = util::description_or_empty(f.description.as_deref());
        // Closure to create enum info + decl
        let make_enum = |ev:&EnumeratedValues, kind:&str, field:&FieldInfo| -> (EnumInfo, TokenStream) {
            let base = enum_base_name(field, ev, config);
