    pub field_ident: Ident,
    pub ty_ident: Ident,
    pub feature: Option<TokenStream>,
}
pub struct PeripheralOut { pub tokens: TokenStream, pub singletons: Vec<Singleton> }

pub fn name_without_dim(name:&str) -> String { name.replace("[%s]", "").replace("%s", "") }
pub fn expand_dim_name(name:&str, idx:&str) -> String { name.replace("[%s]", idx).replace("%s", idx) }

fn periph_description(per:&Peripheral, device:&Device) -> String {
    if let Some(d)=&per.description { let c=util::clean_description(d); if !c.is_empty() { return c; } }
    if let Some(base)=&per.derived_from {
        if let Some(bp)=device.peripherals.iter().find(|p| &p.name==base) {
            if let Some(d)=&bp.description { let c=util::clean_description(d); if !c.is_empty() { return c; } }
        }
    }
    // For a derived peripheral with no description but base also none, fallback? original for root uses name
    per.name.clone()
}
// Description for register/cluster docs with derived fallback resolved in block context below
fn rc_description(rc:&RegisterCluster) -> Option<String> {
    match rc { RegisterCluster::Register(r)=>r.description.as_deref().map(util::clean_description), RegisterCluster::Cluster(c)=>c.description.as_deref().map(util::clean_description) }
}

#[derive(Clone)]
struct BlockEntry {
    offset: u32,
    size_bytes: u32, // layout extent from offset
    doc_offset: u32,
    doc_end: Option<u32>, // if range forced/should
    desc: String,
    accessor_base_name: String, // for ident formatting as accessor (already group/dim adjusted)
    ty: Ident,
    kind: BlockKind,
    orig_index: usize,
    // for range doc of single register with size>32: doc_end computed floor
}
#[derive(Clone)]
enum BlockKind {
    Single { field: Ident },
    Array { field: Ident, len: u32, stride: u32, contiguous: bool, individual: Vec<(String,u32,usize)>, warning_first_expanded_name: Option<String>, has_individual: bool },
}

struct BlockContext<'a> {
    device:&'a Device,
    config:&'a Config,
    // path for errors e.g. "P0" or "P0.CLUSTER"
    path:String,
    // html prefix path segments original names joined by ':' for registers: peripheral original (and cluster names?)
    html_path:String,
}

fn find_rc_in_block<'a>(items:&'a [RegisterCluster], name:&str) -> Option<&'a RegisterCluster> {
    items.iter().find(|rc| rc.name()==name)
}

fn resolve_rc_size(rc:&RegisterCluster, defaults:&RegisterProperties, ctx:&BlockContext, siblings:&[RegisterCluster]) -> anyhow::Result<u32> {
    match rc {
        RegisterCluster::Register(r)=>{
            // if derived and own size missing in resolved chain, try base
            let merged=r.properties.merge(defaults);
            if let Some(sz)=merged.size { Ok(reggen::bits_to_bytes(sz)) } else if let Some(base_name)=&r.derived_from {
                // Only same-block simple names for now; path names handled by finding last component in siblings/device
                let target = find_rc_by_path(base_name, ctx, siblings);
                if let Some(t)=target { resolve_rc_size(t, defaults, ctx, siblings) } else {
                    // let register render produce proper error later; for block use 4?
                    Err(anyhow!("Register {} has no `size` field", r.name))
                }
            } else { Err(anyhow!("Register {} has no `size` field", r.name)) }
        }
        RegisterCluster::Cluster(c)=>{
            if let Some(base_name)=&c.derived_from {
                if let Some(t)=find_rc_by_path(base_name, ctx, siblings) { return resolve_rc_size(t, defaults, ctx, siblings); }
            }
            let child_defaults=c.properties.merge(defaults);
            cluster_size(c, &child_defaults, ctx)
        }
    }
}
fn find_rc_by_path<'a>(path:&str, ctx:&BlockContext<'a>, siblings:&'a [RegisterCluster]) -> Option<&'a RegisterCluster> {
    // Simple name in same block
    if let Some(rc)=find_rc_in_block(siblings, path) { return Some(rc); }
    // Path like PERIPH.REG or PERIPH.CLUSTER.REG ; split by '.'
    let parts:Vec<&str>=path.split('.').collect();
    if parts.len()>=2 {
        if let Some(per)=ctx.device.peripherals.iter().find(|p| p.name==parts[0]) {
            // traverse
            let mut items_opt = per.registers.as_deref();
            let mut found=None;
            for (i,part) in parts.iter().enumerate().skip(1) {
                let Some(items)=items_opt else { break };
                let Some(rc)=items.iter().find(|rc| rc.name()==*part) else { break };
                if i==parts.len()-1 { found=Some(rc); } else if let RegisterCluster::Cluster(cl)=rc { items_opt=Some(&cl.children); } else { break; }
            }
            if found.is_some() { return found; }
        }
    }
    None
}
fn cluster_size(c:&ClusterInfo, defaults:&RegisterProperties, ctx:&BlockContext) -> anyhow::Result<u32> {
    let mut max_end=0u32;
    for child in &c.children {
        let elem_size=resolve_rc_size(child, defaults, ctx, &c.children)?;
        let end = if let Some(dim)=child.dim().dim {
            if ctx.config.max_cluster_size {
                // use increment * dim? approximate
                child.address_offset() + child.dim().dim_increment.unwrap_or(elem_size)*dim
            } else if ctx.config.keep_list {
                child.address_offset() + child.dim().dim_increment.unwrap_or(elem_size)*(dim-1) + elem_size
            } else {
                // array extent: if increment==elem_size then dim*size else strided placeholder extent for cluster size? Original likely dim*size (like docs)
                child.address_offset() + elem_size*dim
            }
        } else { child.address_offset()+elem_size };
        max_end=max_end.max(end);
    }
    Ok(max_end)
}

fn rc_type_and_name(rc:&RegisterCluster, config:&Config) -> (Ident, Ident, String) {
    // Returns (type ident, mod ident (for clusters mod; for registers mod), name_for_type (group+dim-removed))
    match rc {
        RegisterCluster::Register(r)=>{
            let base=name_without_dim(&r.name);
            let name_for_type=if !config.ignore_groups {
                if let Some(g)=&r.alternate_group { format!("{}_{}", g, base) } else { base }
            } else { base };
            (util::ident(&name_for_type,config,"register"), util::ident(&name_for_type,config,"register_mod"), name_for_type)
        }
        RegisterCluster::Cluster(c)=>{
            let base=name_without_dim(&c.name);
            (util::ident(&base,config,"cluster"), util::ident(&base,config,"cluster_mod"), base)
        }
    }
}

fn render_child_modules(items:&[RegisterCluster], defaults:&RegisterProperties, ctx:&BlockContext) -> anyhow::Result<TokenStream> {
    log::debug!("Pushing cluster & register information into output");
    let mut out=TokenStream::new();
    // Group derived items by base name (same block derived_for grouping)
    // Determine for each item if it's derived from another item in same block; root items render, derived attach to root (resolved root)
    #[derive(Clone)]
