        infos.push(info);
    }
    for (idx,rc) in items.iter().enumerate() {
        if matches!(infos[idx], DeriveInfo::Derived(_)) { continue; }
        // Render root
        let tokens=match rc {
            RegisterCluster::Register(r)=>{
                let (_ty,_mod,name_for_type)=rc_type_and_name(rc, ctx.config);
                let html = html_for_register(ctx, &r.name);
                match reggen::render(r, &name_for_type, defaults, ctx.config, &ctx.path, html) {
                    Ok(o)=>o.tokens,
                    Err(e)=>return Err(e.context(format!("can't render register '{}'", r.name)))
                }
            }
            RegisterCluster::Cluster(c)=>{ render_cluster(c, defaults, ctx)? }
        };
        out.extend(tokens);
        // derived children attached to this root
        for (didx,drc) in items.iter().enumerate() {
            if let DeriveInfo::Derived(root_name)=&infos[didx] {
                if root_name!=rc.name() { continue; }
                let (base_ty,base_mod,_)=rc_type_and_name(rc, ctx.config);
                let (der_ty,der_mod,_)=rc_type_and_name(drc, ctx.config);
                match drc {
                    RegisterCluster::Register(_)=>{
                        out.extend(quote!{ pub use #base_ty as #der_ty; pub use #base_mod as #der_mod; });
                    }
                    RegisterCluster::Cluster(dc)=>{
                        let ddesc=dc.description.as_deref().map(util::clean_description).unwrap_or_else(|| dc.name.clone());
                        // In example, doc on first use only
                        out.extend(quote!{ #[doc=#ddesc] pub use #base_ty as #der_ty; pub use #base_mod as #der_mod; });
                    }
                }
            }
        }
    }
    Ok(out)
}

fn html_for_register(ctx:&BlockContext, reg_name:&str) -> Option<String> {
    ctx.config.settings.html_url.as_ref().map(|url| format!("{}#{}:{}", url, ctx.html_path, reg_name))
}

fn render_cluster(c:&ClusterInfo, defaults:&RegisterProperties, ctx:&BlockContext) -> anyhow::Result<TokenStream> {
    let child_defaults=c.properties.merge(defaults);
    let (ty,mod_ident,name_for_type)=rc_type_and_name(&RegisterCluster::Cluster(c.clone()), ctx.config);
    let _=name_for_type;
    let desc=c.description.as_deref().map(util::clean_description).unwrap_or_else(|| c.name.clone());
    let child_ctx=BlockContext{ device:ctx.device, config:ctx.config, path:format!("{}.{}", ctx.path, c.name), html_path:format!("{}:{}", ctx.html_path, c.name) };
    // nested child modules
    let child_modules=render_child_modules(&c.children, &child_defaults, &child_ctx)?;
    // block struct for cluster
    let block=render_block_struct(&c.children, &child_defaults, &child_ctx, BlockStructKind::Cluster{ ty:&ty, desc:&desc, orig_name:&c.name }, c)?;
    let alias_attr=if util::ident_str(&name_without_dim(&c.name), ctx.config, "cluster") != name_without_dim(&c.name) { let a=name_without_dim(&c.name); quote!{ #[doc(alias=#a)] } } else { quote!{} };
    // block returns struct+impl tokens including alias? We'll incorporate struct definition inside render_block_struct for cluster, which includes doc/alias.
    Ok(quote!{
        #[doc=#desc] pub use self::#mod_ident::#ty;
        #[doc=r"Cluster"]
        #[doc=#desc]
        pub mod #mod_ident {
            #block
            #child_modules
        }
    })
}

enum BlockStructKind<'a> {
    Peripheral,
    Cluster{ ty:&'a Ident, desc:&'a str, orig_name:&'a str },
}

fn render_block_struct(items:&[RegisterCluster], defaults:&RegisterProperties, ctx:&BlockContext, kind:BlockStructKind, cluster_info:Option<&ClusterInfo>) -> anyhow::Result<TokenStream> {
    log::debug!("Pushing {} register or cluster blocks into output", items.len());
    log::debug!("Expanding registers or clusters into Register Block Fields");
    // trace for registers in this block (original traces for nested were at peripheral expansion stage; cluster nested trace ordering approximate)
    // Expand entries
    let mut entries:Vec<BlockEntry>=Vec::new();
    for (idx,rc) in items.iter().enumerate() {
        // Description with derived fallback (same block)
        let mut desc=rc_description(rc).unwrap_or_default();
        if desc.is_empty() {
            if let Some(df)=rc.derived_from() {
                if let Some(base)=find_rc_by_path(df,ctx,items) { desc=rc_description(base).unwrap_or_default(); }
            }
        }
        let (ty,_mod_id,name_for_type)=rc_type_and_name(rc, ctx.config);
        let elem_size=resolve_rc_size(rc, defaults, ctx, items).with_context(|| match rc { RegisterCluster::Register(r)=>format!("can't render register '{}'", r.name), RegisterCluster::Cluster(c)=>format!("can't render cluster '{}'", c.name) })?;
        let offset=rc.address_offset();
        let dim_elem=rc.dim();
        if let Some(dim)=dim_elem.dim {
            if dim_elem.dim_increment.is_none() {
                // Create a single entry using original name (will panic in ident for %s like original)
                let field=util::ident(&rc.name(), ctx.config, match rc { RegisterCluster::Register(_)=>"register_accessor", RegisterCluster::Cluster(_)=>"cluster_accessor" });
                let _=field;
                // also force ty ident from original to panic message Ch%s (Pascal) as original: order in original is ty first likely
                let _bad=util::ident(&rc.name(), ctx.config, match rc { RegisterCluster::Register(_)=>"register", RegisterCluster::Cluster(_)=>"cluster" });
                // If no panic (name was [%s] sanitized? % still panic), fallback continue as single
                entries.push(BlockEntry{ offset, size_bytes:elem_size, doc_offset:offset, doc_end:None, desc:desc.clone(), accessor_base_name:name_for_type.clone(), ty:ty.clone(), kind:BlockKind::Single{field:util::ident(&name_for_type,ctx.config,match rc { RegisterCluster::Register(_)=>"register_accessor", RegisterCluster::Cluster(_)=>"cluster_accessor" })}, orig_index:idx });
                continue;
            }
            let increment=dim_elem.dim_increment.unwrap();
            let indices=dim_elem.indices().unwrap_or_default();
            if ctx.config.keep_list {
                for (i,idx_str) in indices.iter().enumerate() {
                    let expanded=expand_dim_name(&rc.name(), idx_str);
                    // accessor name base should include group for registers
                    let acc_base=if let RegisterCluster::Register(r)=rc {
                        if !ctx.config.ignore_groups { if let Some(g)=&r.alternate_group { format!("{}_{}",g,expanded) } else { expanded } } else { expanded }
                    } else { expanded };
                    let field=util::ident(&acc_base, ctx.config, match rc { RegisterCluster::Register(_)=>"register_accessor", RegisterCluster::Cluster(_)=>"cluster_accessor" });
                    entries.push(BlockEntry{ offset: offset + (i as u32)*increment, size_bytes:elem_size, doc_offset:offset, doc_end:None, desc:desc.clone(), accessor_base_name:acc_base, ty:ty.clone(), kind:BlockKind::Single{field}, orig_index:idx });
                }
            } else {
                // array entry
                let acc_base_name = if let Some(dn)=&dim_elem.dim_name { dn.clone() } else { name_for_type.clone() };
                let field=util::ident(&acc_base_name, ctx.config, match rc { RegisterCluster::Register(_)=>"register_accessor", RegisterCluster::Cluster(_)=>"cluster_accessor" });
                let contiguous = increment==elem_size;
                let has_individual = dim_elem.dim_name.is_none() && rc.name().matches("%s").count()==1 && !rc.name().ends_with("[%s]");
                let mut individual=Vec::new();
                if has_individual {
                    for (i,idx_str) in indices.iter().enumerate() {
                        let expanded=expand_dim_name(&rc.name(), idx_str);
                        let acc_base=if let RegisterCluster::Register(r)=rc {
                            if !ctx.config.ignore_groups { if let Some(g)=&r.alternate_group { format!("{}_{}",g,expanded) } else { expanded } } else { expanded }
                        } else { expanded };
                        individual.push((acc_base, offset+(i as u32)*increment, i));
                    }
                }
                let warning = if dim_elem.dim_index.is_some() {
                    // Original warning when dimIndex present: doc line naming first expanded register.
                    // Determined by first index expanded name (original)
                    let first_idx=indices.get(0).cloned().unwrap_or_default();
                    Some(expand_dim_name(&rc.name(), &first_idx))
                } else { None };
                let size_bytes = if contiguous { elem_size*dim } else { 0 };
                let doc_end = offset + elem_size*dim;
                entries.push(BlockEntry{ offset, size_bytes, doc_offset:offset, doc_end:Some(doc_end), desc:desc.clone(), accessor_base_name:acc_base_name, ty:ty.clone(), kind:BlockKind::Array{ field, len:dim, stride:increment, contiguous, individual, warning_first_expanded_name:warning, has_individual }, orig_index:idx });
            }
        } else {
            let field=util::ident(&name_for_type, ctx.config, match rc { RegisterCluster::Register(_)=>"register_accessor", RegisterCluster::Cluster(_)=>"cluster_accessor" });
            // doc range for single
            let doc_end = match rc {
                RegisterCluster::Register(r)=>{
                    let merged=r.properties.merge(defaults);
                    if let Some(sz)=merged.size { if sz>32 { Some(offset + sz/8) } else { None } } else { None }
                }
                RegisterCluster::Cluster(_)=>{
                    if elem_size>4 { Some(offset+elem_size) } else { None }
                }
            };
            entries.push(BlockEntry{ offset, size_bytes:elem_size, doc_offset:offset, doc_end, desc:desc.clone(), accessor_base_name:name_for_type.clone(), ty:ty.clone(), kind:BlockKind::Single{field}, orig_index:idx });
        }
    }
    // Sort entries by offset (stable by original expanded order as in entries order)
    entries.sort_by_key(|e| e.offset);
    // Group overlaps
    #[derive(Clone)]
    struct Group { start:u32, end:u32, entries:Vec<BlockEntry> }
    let mut groups:Vec<Group>=Vec::new();
    for e in entries {
        if let Some(g)=groups.last_mut() {
            // overlap if e.offset < g.end  (note zero-size entries: if size 0, offset<end still may group; original size0 case weird ignore)
            if e.offset < g.end {
                g.end=g.end.max(e.offset+e.size_bytes);
                g.entries.push(e);
                continue;
            }
        }
        groups.push(Group{ start:e.offset, end:e.offset+e.size_bytes, entries:vec![e] });
    }
    // Build struct fields and accessors
    let mut struct_fields=TokenStream::new();
    let mut accessors=TokenStream::new();
    let mut cursor=0u32;
    for (gi,g) in groups.iter().enumerate() {
        if g.start>cursor {
            let size=g.start-cursor;
            let fname=util::ident_raw(&format!("_reserved{}", gi));
            let lit=util::hex_literal(size as u64);
            struct_fields.extend(quote!{ #fname: [u8; #lit], });
            cursor=g.start;
        }
        if g.entries.len()==1 {
            let e=&g.entries[0];
            match &e.kind {
                BlockKind::Single{field}=>{
                    let ty=&e.ty;
                    struct_fields.extend(quote!{ #field: #ty, });
                    let doc=make_doc(e);
                    accessors.extend(quote!{ #[doc=#doc] #[inline(always)] pub const fn #field(&self) -> &#ty { &self.#field } });
                }
                BlockKind::Array{field,len,stride,contiguous,individual,warning_first_expanded_name,has_individual}=>{
                    let ty=&e.ty;
                    let len_lit=Literal::u32_unsuffixed(*len);
                    if *contiguous {
                        struct_fields.extend(quote!{ #field: [#ty; #len_lit], });
                    } else {
                        struct_fields.extend(quote!{ #field: (), });
                    }
                    let doc=make_doc(e);
                    let acc_ident=field.clone();
                    let warning_tokens = if let Some(first_name)=warning_first_expanded_name {
                        // Only include warning if dimIndex was explicitly present; original included for A,B,C but what about explicit 0,1,2? We'll mimic based on enabler set in expansion (Some only when dim_index present)
                        let warn_doc="";
                        let warn2=format!("<div class=\"warning\">`n` is the index of register in the array. `n == 0` corresponds to `{}` register.</div>", first_name);
                        // Note for clusters, wording may say cluster? Probe later.
                        quote!{ #[doc=#warn_doc] #[doc=#warn2] }
                    } else { quote!{} };
                    if *contiguous {
                        accessors.extend(quote!{
                            #[doc=#doc] #warning_tokens #[inline(always)] pub const fn #acc_ident(&self, n: usize) -> &#ty { &self.#field[n] }
                        });
                        let iter_name=util::ident_raw(&format!("{}_iter", field.to_string()));
                        // Original iter name is field accessor ident_str + "_iter" but through ident formatting? For ch_ case it became ch__iter (field ch_ + _iter) matches.
                        accessors.extend(quote!{
                            #[doc="Iterator for array of:"] #[doc=#doc] #[inline(always)] pub fn #iter_name(&self) -> impl Iterator<Item=&#ty> { self.#field.iter() }
                        });
                    } else {
                        let stride_lit=Literal::u32_unsuffixed(*stride);
                        let offset_lit_opt = if e.offset!=0 { let l=Literal::u32_unsuffixed(e.offset); quote!{ .add(#l) } } else { quote!{} };
                        accessors.extend(quote!{
                            #[doc=#doc] #warning_tokens #[inline(always)] pub const fn #acc_ident(&self, n: usize) -> &#ty { #[allow(clippy::no_effect)] [(); #len_lit][n]; unsafe { &*core::ptr::from_ref(self).cast::<u8>() #offset_lit_opt .add(#stride_lit * n).cast() } }
                        });
                        let iter_name=util::ident_raw(&format!("{}_iter", field.to_string()));
                        accessors.extend(quote!{
                            #[doc="Iterator for array of:"] #[doc=#doc] #[inline(always)] pub fn #iter_name(&self) -> impl Iterator<Item=&#ty> { (0..#len_lit).map(move |n| unsafe { &*core::ptr::from_ref(self).cast::<u8>() #offset_lit_opt .add(#stride_lit * n).cast() }) }
                        });
                    }
                    if *has_individual && *contiguous {
                        for (acc_base, off, i) in individual {
                            let acc=util::ident(acc_base, ctx.config, "register_accessor");
                            // Note for clusters, accessor ident type is cluster_accessor, but our acc_base for clusters was stored; individual generation here always register_accessor currently – for clusters the config types are both snake defaults, custom formats would differ. TODO determine by entry original kind.
                            // Doc uses entry desc with individual offset
                            let idoc=format!("{} - {}", util::offset_str(*off as u64), e.desc);
                            let ilit=Literal::usize_unsuffixed(*i);
                            accessors.extend(quote!{ #[doc=#idoc] #[inline(always)] pub const fn #acc(&self) -> &#ty { self.#acc_ident(#ilit) } });
                        }
                    }
                }
            }
            cursor=g.end;
        } else {
            // overlap group
            let first=&g.entries[0];
            let first_field_name = match &first.kind { BlockKind::Single{field}=>field.to_string(), BlockKind::Array{field,..}=>field.to_string() };
            let reserved_name=util::ident_raw(&format!("_reserved_{}_{}", gi, first_field_name));
            let size=g.end-g.start;
            let lit=util::hex_literal(size as u64);
            struct_fields.extend(quote!{ #reserved_name: [u8; #lit], });
            // accessor order: sorted by offset asc, orig_index desc for ties
            let mut acc_entries=g.entries.clone();
            acc_entries.sort_by(|a,b| a.offset.cmp(&b.offset).then(b.orig_index.cmp(&a.orig_index)));
            for e in &acc_entries {
                let ty=&e.ty;
                let doc=make_doc(e);
                match &e.kind {
                    BlockKind::Single{field}=>{
                        let add_tokens=if e.offset==0 { quote!{} } else { let l=Literal::u32_unsuffixed(e.offset); quote!{ .add(#l) } };
                        accessors.extend(quote!{ #[doc=#doc] #[inline(always)] pub const fn #field(&self) -> &#ty { unsafe { &*core::ptr::from_ref(self).cast::<u8>() #add_tokens .cast() } } });
                    }
                    BlockKind::Array{field,len,stride,contiguous,..}=>{
                        // Overlapping arrays are complex; approximate with pointer-based array accessor similar strided
                        let len_lit=Literal::u32_unsuffixed(*len); let stride_lit=Literal::u32_unsuffixed(*stride);
                        let base_add=if e.offset==0 { quote!{} } else { let l=Literal::u32_unsuffixed(e.offset); quote!{ .add(#l) } };
                        accessors.extend(quote!{ #[doc=#doc] #[inline(always)] pub const fn #field(&self, n: usize) -> &#ty { #[allow(clippy::no_effect)] [(); #len_lit][n]; unsafe { &*core::ptr::from_ref(self).cast::<u8>() #base_add .add(#stride_lit*n).cast() } } });
                        let _=contiguous;
                    }
                }
            }
            cursor=g.end;
        }
    }
    let debug_attr = if ctx.config.impl_debug {
        match &ctx.config.impl_debug_feature { Some(f)=>quote!{ #[cfg_attr(feature=#f, derive(Debug))] }, None=>quote!{ #[derive(Debug)] } }
    } else { quote!{} };
    match kind {
        BlockStructKind::Peripheral=>{
            Ok(quote!{
                #[repr(C)]
                #debug_attr
                #[doc="Register block"]
                pub struct RegisterBlock { #struct_fields }
                impl RegisterBlock { #accessors }
            })
        }
        BlockStructKind::Cluster{ty,desc,orig_name}=>{
            let alias_attr=if util::ident_str(&name_without_dim(orig_name), ctx.config, "cluster") != name_without_dim(orig_name) { let a=name_without_dim(orig_name); quote!{ #[doc(alias=#a)] } } else { quote!{} };
            let _=cluster_info;
            Ok(quote!{
                #[repr(C)]
                #debug_attr
                #[doc=#desc]
                #alias_attr
                pub struct #ty { #struct_fields }
                impl #ty { #accessors }
            })
        }
    }
}
fn make_doc(e:&BlockEntry) -> String {
    // If desc empty, original doc in block accessor: cluster empty desc fallback name handled in desc for clusters; registers with missing desc gave ? e.desc empty -> "0x00 - " or "0x00"? Need probe; for now if empty use just offset? Let's check later and adjust by harness.
    if let Some(end)=e.doc_end {
        if e.desc.is_empty() { format!("{}..{}", util::offset_str(e.doc_offset as u64), util::offset_str(end as u64)) } else { format!("{}..{} - {}", util::offset_str(e.doc_offset as u64), util::offset_str(end as u64), e.desc) }
    } else {
        if e.desc.is_empty() { util::offset_str(e.doc_offset as u64) } else { format!("{} - {}", util::offset_str(e.doc_offset as u64), e.desc) }
    }
}

pub fn render(per:&Peripheral, device:&Device, config:&Config) -> anyhow::Result<PeripheralOut> {
    log::debug!("Checking derivation information");
    let base_address = per.base_address;
    let desc = periph_description(per, device);
    // Derived peripheral
    if let Some(base_name)=&per.derived_from {
        // Find base peripheral (resolve chain root)
        let mut root_name=base_name.clone();
        for _ in 0..20 {
            if let Some(bp)=device.peripherals.iter().find(|p| &p.name==&root_name) {
                if let Some(next)=&bp.derived_from { root_name=next.clone(); continue; }
            }
            break;
        }
        let base_per_opt=device.peripherals.iter().find(|p| &p.name==&root_name);
        // If base not found, original may panic/error – for now make root_name as given
        let base_mod_name=name_without_dim(&root_name);
        // If base peripheral is dim array, its module name is dim-removed (already)
        let base_mod=util::ident(&base_mod_name, config, "peripheral_mod");
        // expand this peripheral if dim
        let mut singletons=Vec::new(); let mut tokens=TokenStream::new();
        let instances = peripheral_instances(per);
        for (inst_name, addr) in &instances {
            let singleton_tokens=render_singleton(per, inst_name, *addr, &desc, &base_mod, config, device);
            tokens.extend(singleton_tokens);
            // alias module use
            let inst_mod=util::ident(inst_name, config, "peripheral_mod");
            // doc for alias module is desc (in derived example)
            tokens.extend(quote!{ #[doc=#desc] pub use self::#base_mod as #inst_mod; });
            singletons.push(make_singleton_info(inst_name, config, per));
        }
        // If base peripheral itself would be skipped (no registers), derived peripheral probably also skipped? If base has no registers, original may still emit? Probe later.
        let _=base_per_opt;
        return Ok(PeripheralOut{tokens,singletons});
    }
    // Root or dim array peripheral
    let registers = match &per.registers { Some(r) if !r.is_empty()=>r, _=>return Ok(PeripheralOut{tokens:TokenStream::new(), singletons:vec![]}) };
    let device_defaults = device.properties;
    let per_defaults = per.properties.merge(&device_defaults);
    let mod_base_name=name_without_dim(&per.name);
    let mod_ident=util::ident(&mod_base_name, config, "peripheral_mod");
    let ctx=BlockContext{ device, config, path:per.name.clone(), html_path:per.name.clone() };
    // trace expansion for registers (approximate original traces)
    emit_register_traces(&per.name, registers, config);
    // Render child modules first
    let child_modules=render_child_modules(registers, &per_defaults, &ctx).map_err(|e| e)?;
    // RegisterBlock
    let block=render_block_struct(registers, &per_defaults, &ctx, BlockStructKind::Peripheral, None)?;
    // Singletons
    let instances=peripheral_instances(per);
    let mut tokens=TokenStream::new(); let mut singletons=Vec::new();
    for (inst_name, addr) in &instances {
        tokens.extend(render_singleton(per, inst_name, *addr, &desc, &mod_ident, config, device));
        singletons.push(make_singleton_info(inst_name, config, per));
    }
    tokens.extend(quote!{
        #[doc=#desc]
        pub mod #mod_ident {
            #block
            #child_modules
        }
    });
    Ok(PeripheralOut{tokens,singletons})
}

fn emit_register_traces(per_name:&str, items:&[RegisterCluster], _config:&Config) {
    // Original trace in peripheral::render at checking derivation and expanding phases has complex order; output only matters at trace level.
    fn walk(items:&[RegisterCluster], per_name:&str, path:&[String]) {
        for rc in items {
            match rc {
                RegisterCluster::Register(r)=>{
                    let derive_str = match &r.derived_from {
                        Some(df)=>{
                            let block_path = if path.is_empty() { format!("BlockPath {{ peripheral: \"{}\", path: [] }}", per_name) } else { format!("BlockPath {{ peripheral: \"{}\", path: {:?} }}", per_name, path) };
                            format!("Explicit(RegisterPath {{ block: {}, name: \"{}\" }})", block_path, df)
                        }
                        None=>"Root".into()
                    };
                    log::trace!("Register: {}, DeriveInfo: {}", r.name, derive_str);
                }
                RegisterCluster::Cluster(c)=>{
                    let mut p=path.to_vec(); p.push(c.name.clone()); walk(&c.children, per_name, &p);
                }
            }
        }
    }
    walk(items, per_name, &[]);
}

fn peripheral_instances(per:&Peripheral) -> Vec<(String,u64)> {
    if let Some(dim)=per.dim.dim {
        let indices=per.dim.indices().unwrap_or_default();
        let incr=per.dim.dim_increment.unwrap_or(0) as u64;
        let _=dim;
        indices.iter().enumerate().map(|(i,idx)| (expand_dim_name(&per.name, idx), per.base_address + (i as u64)*incr)).collect()
    } else { vec![(per.name.clone(), per.base_address)] }
}

fn feature_token(per:&Peripheral, config:&Config, inst_name:&str) -> Option<(TokenStream,String)> {
    // feature_group: use group_name as feature; feature_peripheral: use peripheral name as feature
    // feature name formatting type peripheral_feature applied to group/peripheral name string
    if config.feature_peripheral {
        let fname=util::ident_str(inst_name, config, "peripheral_feature");
        Some((quote!{ #[cfg(feature=#fname)] }, fname))
    } else if config.feature_group {
        if let Some(g)=&per.group_name { let fname=util::ident_str(g, config, "peripheral_feature"); Some((quote!{ #[cfg(feature=#fname)] }, fname)) } else { None }
    } else { None }
}

fn render_singleton(per:&Peripheral, inst_name:&str, addr:u64, desc:&str, mod_ident:&Ident, config:&Config, _device:&Device) -> TokenStream {
    let ty=util::ident(inst_name, config, "peripheral");
    let spec=util::ident(inst_name, config, "peripheral_spec");
    let ty_str=ty.to_string();
    let addr_lit=util::hex_literal(addr);
    let feature_cfg = feature_token(per,config,inst_name).map(|(t,_)| t).unwrap_or_else(|| quote!{});
    // docs with html
    let doc_tokens = if let Some(url)=&config.settings.html_url {
        let see=format!("See peripheral [structure]({}#{})", url, inst_name);
        quote!{ #[doc=#desc] #[doc=""] #[doc=#see] }
    } else { quote!{ #[doc=#desc] } };
    quote!{
        #feature_cfg
        #doc_tokens
        pub type #ty = crate::Periph<#spec>;
        pub struct #spec;
        impl crate::PeripheralSpec for #spec { type RB = #mod_ident::RegisterBlock; const ADDRESS: usize = #addr_lit; const NAME: &'static str = #ty_str; }
    }
}
fn make_singleton_info(inst_name:&str, config:&Config, per:&Peripheral) -> Singleton {
