use crate::config::{Config, Edition, Target};
use crate::generate::{interrupt, peripheral};
use crate::svd::Device;
use anyhow::Context;
use proc_macro2::TokenStream;
use quote::quote;
use std::path::PathBuf;

pub struct DeviceOutput { pub lib: TokenStream, pub device_x: Option<String>, pub build_rs: Option<TokenStream> }

const GENERIC_SRC: &str = include_str!("../../assets/generic.rs.txt");
const GENERIC_ATOMIC_SRC: &str = include_str!("../../assets/generic_atomic.rs.txt");

fn generic_file_content(config:&Config) -> String {
    let mut s=GENERIC_SRC.to_string();
    if config.atomics {
        if let Some(feat)=&config.atomics_feature {
            s.push_str(&format!("#[cfg(feature = {:?})]\n", feat));
        }
        s.push_str(GENERIC_ATOMIC_SRC);
    }
    s
