fn generic_inline_tokens(config:&Config) -> TokenStream {
    let mut file: syn::File = syn::parse_file(GENERIC_SRC).unwrap();
    if config.atomics {
        let mut atomic_file: syn::File = syn::parse_file(GENERIC_ATOMIC_SRC).unwrap();
        if let Some(feat)=&config.atomics_feature {
            for item in &mut atomic_file.items {
                if let syn::Item::Mod(m)=item {
                    let attr: syn::Attribute = syn::parse_quote!(#[cfg(feature=#feat)]);
                    m.attrs.insert(0, attr);
                }
            }
        }
        file.items.extend(atomic_file.items);
    }
    let items=&file.items;
    quote!{
        #[allow(unused_imports)] use generic::*;
        #[doc = r"Common register and bit access and modify traits"]
        pub mod generic { #(#items)* }
    }
}

