    if !config.skip_crate_attributes {
        let doc=format!("Peripheral access API for {} microcontrollers (generated using svd2rust v{})\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust", device.name.to_uppercase(), crate::config::VERSION);
        lib.extend(quote!{ #![doc=#doc] });
        if !config.make_mod {
