    if let Some(cpu)=&device.cpu {
        let prio=proc_macro2::Literal::u8_unsuffixed(cpu.nvic_prio_bits);
        lib.extend(quote!{
            #[doc=r"Number available in the NVIC for configuring priority"]
            pub const NVIC_PRIO_BITS: u8 = #prio;
