        let prio=proc_macro2::Literal::u8_unsuffixed(cpu.nvic_prio_bits);
        lib.extend(quote!{
            #[doc=r"Number available in the NVIC for configuring priority"]
            pub const NVIC_PRIO_BITS: u8 = #prio;
        });
    }
    if config.target==Target::CortexM && config.reexport_core_peripherals {
        lib.extend(quote!{
            pub use cortex_m::peripheral::Peripherals as CorePeripherals;
            pub use cortex_m::peripheral::{CBP, CPUID, DCB, DWT, FPB, FPU, ITM, MPU, NVIC, SCB, SYST, TPIU,};
        });
    }
    if config.target==Target::CortexM && config.reexport_interrupt {
        lib.extend(quote!{
            #[cfg(feature="rt")] pub use cortex_m_rt::interrupt;
            #[cfg(feature="rt")] pub use self::Interrupt as interrupt;
        });
    }
    // generic tokens
    if config.generic_mod {
        if !config.make_mod {
            lib.extend(quote!{
                #[allow(unused_imports)] use generic::*;
                #[doc="Common register and bit access and modify traits"]
                pub mod generic;
            });
        }
    } else {
        lib.extend(generic_inline_tokens(config));
    }
    // interrupts
    log::debug!("Rendering interrupts");
    let interrupts=interrupt::collect(device, config);
    if config.target==Target::RISCV {
        if config.settings.riscv_config.is_none() {
            log::warn!("No settings file provided for RISC-V target. Using legacy interrupts rendering");
            log::warn!("Please, consider migrating your PAC to riscv 0.12.0 or later");
        } else {
            let rc=config.settings.riscv_config.as_ref().unwrap();
            if rc.base_isa.is_none() {
                log::warn!(target:"svd2rust::config::riscv", "No base RISC-V ISA specified in settings file.");
                log::warn!(target:"svd2rust::config::riscv", "If your target supports vectored mode, you must specify the base ISA.");
                log::warn!(target:"svd2rust::config::riscv", "Otherwise, `riscv-rt` macros will not provide start trap routines to core interrupt handlers");
            }
        }
    }
    lib.extend(interrupt::render(device, config, &interrupts));
    // peripherals
    let mut singletons:Vec<peripheral::Singleton>=Vec::new();
    for per in &device.peripherals {
        log::debug!("Rendering peripheral {}", per.name);
        let group_name = per.group_name.as_deref().unwrap_or("No group name");
        let out=peripheral::render(per, device, config).with_context(|| format!("can't render peripheral '{}', group '{}'", per.name, group_name))?;
        lib.extend(out.tokens);
        singletons.extend(out.singletons);
    }
    // Peripherals struct
    let fields=singletons.iter().map(|s| {
        let doc=&s.doc_name; let field=&s.field_ident; let ty=&s.ty_ident; let feat=s.feature.clone().unwrap_or_else(|| quote!{});
        quote!{ #feat #[doc=#doc] pub #field: #ty, }
    });
    let steals=singletons.iter().map(|s| {
        let field=&s.field_ident; let ty=&s.ty_ident;
        if matches!(config.edition, Edition::E2024) { quote!{ #field: unsafe { #ty::steal() }, } } else { quote!{ #field: #ty::steal(), } }
    });
    let no_mangle = if matches!(config.edition, Edition::E2024) { quote!{ #[unsafe(no_mangle)] } } else { quote!{ #[no_mangle] } };
    let steal_body = if matches!(config.edition, Edition::E2024) {
        quote!{ unsafe { DEVICE_PERIPHERALS = true } Peripherals { #(#steals)* } }
    } else { quote!{ DEVICE_PERIPHERALS = true; Peripherals { #(#steals)* } } };
    lib.extend(quote!{
        #no_mangle static mut DEVICE_PERIPHERALS: bool = false;
        /// All the peripherals.
        #[allow(non_snake_case)]
        pub struct Peripherals { #(#fields)* }
        impl Peripherals {
            /// Returns all the peripherals *once*.
            #[cfg(feature="critical-section")]
            #[inline]
            pub fn take() -> Option<Self> { critical_section::with(|_| { if unsafe { DEVICE_PERIPHERALS } { return None } Some(unsafe { Peripherals::steal() }) }) }
            /// Unchecked version of `Peripherals::take`.
            ///
            /// # Safety
            ///
            /// Each of the returned peripherals must be used at most once.
            #[inline]
            pub unsafe fn steal() -> Self { #steal_body }
        }
    });
    let (device_x, build_rs)=match config.target {
        Target::CortexM|Target::Msp430|Target::RISCV|Target::XtensaLX => {
            let dx = if config.target==Target::RISCV && config.settings.riscv_config.is_some() {
                // new riscv rendering may produce different device.x (probe later); for now same list
                interrupt::device_x(&interrupts)
            } else { interrupt::device_x(&interrupts) };
            (Some(dx), Some(build_tokens()))
        }
        _=>(None,None)
    };
    Ok(DeviceOutput{lib, device_x, build_rs})
}

fn build_tokens() -> TokenStream {
    quote!{
        //! Builder file for Peripheral access crate generated by svd2rust tool
        use std::env;
        use std::fs::File;
        use std::io::Write;
        use std::path::PathBuf;
        fn main() {
            if env::var_os("CARGO_FEATURE_RT").is_some() {
                let out = &PathBuf::from(env::var_os("OUT_DIR").unwrap());
                File::create(out.join("device.x")).unwrap().write_all(include_bytes!("device.x")).unwrap();
                println!("cargo:rustc-link-search={}", out.display());
                println!("cargo:rerun-if-changed=device.x");
            }
            println!("cargo:rerun-if-changed=build.rs");
        }
    }
}
