import sys; sys.path.insert(0,"/tmp")
from compare import compare_case
def make_svd(peripherals, default="<size>32</size><access>read-write</access><resetValue>0x0</resetValue><resetMask>0xFFFFFFFF</resetMask>", cpu=True):
    cpu_xml="<cpu><name>CM3</name><revision>r1p0</revision><endian>little</endian><mpuPresent>true</mpuPresent><fpuPresent>true</fpuPresent><nvicPrioBits>4</nvicPrioBits><vendorSystickConfig>false</vendorSystickConfig></cpu>" if cpu else ""
    return f"<device><name>Dev</name><version>0.1</version><description>Device</description>{cpu_xml}<addressUnitBits>8</addressUnitBits><width>32</width>{default}<peripherals>{peripherals}</peripherals></device>"
def per(body, name="P0", base="0x1000", extra=""):
    return f"<peripheral {extra}><name>{name}</name><description>{name} desc</description><baseAddress>{base}</baseAddress>{body}</peripheral>"
def regs_wrap(regs): return f"<registers>{regs}</registers>"
def reg(name="R", off=0, extra="", fields=""):
    return f"<register><name>{name}</name><description>{name} desc</description><addressOffset>{off}</addressOffset>{extra}{fields}</register>"
def field(name="F", off=0, w=1, extra=""):
    return f"<field><name>{name}</name><description>{name} desc</description><bitOffset>{off}</bitOffset><bitWidth>{w}</bitWidth>{extra}</field>"
def fields_wrap(fs): return f"<fields>{fs}</fields>"

cases=[]
def add(name, svd, args=[]): cases.append({"name":name,"svd":svd,"args":args})
