for mwv in ["oneToClear","oneToSet","oneToToggle","zeroToClear","zeroToSet","zeroToToggle","clear","set","modify"]:
    f=field("EN",2,1,f"<modifiedWriteValues>{mwv}</modifiedWriteValues>")
    add(f"mwv_bit_{mwv}", make_svd(per(regs_wrap(reg("R",0,"",fields_wrap(f))))))
    f2=field("MODE",4,3,f"<modifiedWriteValues>{mwv}</modifiedWriteValues>")
    add(f"mwv_field_{mwv}", make_svd(per(regs_wrap(reg("R",0,"",fields_wrap(f2))))))
    add(f"mwv_reg_{mwv}", make_svd(per(regs_wrap(reg("R",0,f"<modifiedWriteValues>{mwv}</modifiedWriteValues>",fields_wrap(field("A",0,2)+field("B",4,1)))))))
# readAction has any effect?
for ra in ["clear","set","modify","modifyExternal"]:
    add(f"readaction_{ra}", make_svd(per(regs_wrap(reg("R",0,f"<readAction>{ra}</readAction>",fields_wrap(field()))))))
# dataType
for dt in ["uint8_t","uint16_t","uint32_t *","int32_t"]:
    add("datatype_"+dt.replace(" ","").replace("*","ptr"), make_svd(per(regs_wrap(reg("R",0,f"<dataType>{dt}</dataType>")))))
# writeconstraint variants field and reg
for name,wc in [("war","<writeAsRead>true</writeAsRead>"),("uev","<useEnumeratedValues>true</useEnumeratedValues>"),("range_full","<range><minimum>0</minimum><maximum>1023</maximum></range>"),("range_part","<range><minimum>0</minimum><maximum>5</maximum></range>")]:
    add(f"wc_field_{name}", make_svd(per(regs_wrap(reg("R",0,"",fields_wrap(field("F",0,10,f"<writeConstraint>{wc}</writeConstraint>")))))))
    add(f"wc_reg_{name}", make_svd(per(regs_wrap(reg("R",0,f"<writeConstraint>{wc}</writeConstraint>",fields_wrap(field("F",0,10)))))))
for c in cases: compare_case(c)
