new='''    let features_toml = if config.feature_group || config.feature_peripheral {
        let mut content = String::from("# Below are the FEATURES generated by svd2rust base on groupName in SVD file.\\n# Please copy them to Cargo.toml.\\n[features]\\n");
        let fmt_list = |v:&Vec<String>| format!("[{}]", v.iter().map(|x| format!("\\"{}\\"", x)).collect::<Vec<_>>().join(","));
        if config.feature_group {
            let mut groups: Vec<String> = Vec::new();
            for per in &device.peripherals {
                if let Some(g)=&per.group_name {
                    let f=crate::util::ident_str(g, config, "peripheral_feature");
                    if !groups.contains(&f) { groups.push(f); }
                }
            }
            groups.sort();
            for g in &groups { content.push_str(&format!("{} = []\\n", g)); }
            content.push_str(&format!("all-groups = {}\\n", fmt_list(&groups)));
        }
        if config.feature_peripheral {
            let mut pers: Vec<String> = Vec::new();
            for per in &device.peripherals {
                // expanded instances
                let inst_names: Vec<String> = if per.dim.dim.is_some() {
                    per.dim.indices().unwrap_or_default().iter().map(|idx| crate::generate::peripheral::expand_dim_name(&per.name, idx)).collect()
                } else { vec![per.name.clone()] };
                for inst in inst_names {
                    let f=crate::util::ident_str(&inst, config, "peripheral_feature");
                    if !pers.contains(&f) { pers.push(f); }
                }
            }
            pers.sort();
            for g in &pers { content.push_str(&format!("{} = []\\n", g)); }
            content.push_str(&format!("all-peripherals = {}\\n", fmt_list(&pers)));
        }
        Some(content)
    } else { None };
    '''
