        RegisterCluster::Register(r)=>r.derived_from.is_some() && r.fields.is_none(),
        RegisterCluster::Cluster(c)=>c.derived_from.is_some() && c.children.is_empty(),
    }
}
struct ExternalTarget {
    parent_segments: Vec<Ident>,
    target: RegisterCluster,
}
fn find_in_items_by_name_or_expanded<'a>(items:&'a [RegisterCluster], name:&str) -> Option<&'a RegisterCluster> {
    for rc in items {
        if rc.name()==name { return Some(rc); }
        if rc.dim().dim.is_some() {
            if let Some(idxs)=rc.dim().indices() {
                if idxs.iter().any(|idx| expand_dim_name(rc.name(), idx)==name) { return Some(rc); }
            }
        }
    }
    None
}
fn resolve_external(df:&str, want_cluster:bool, ctx:&BlockContext) -> anyhow::Result<ExternalTarget> {
    let kind_name = if want_cluster { "cluster" } else { "register" };
    let parts:Vec<&str>=df.split('.').collect();
    if parts.len()>=2 {
        // find peripheral
        let mut per_found=None;
        for per in &ctx.device.peripherals {
            if per.name==parts[0] { per_found=Some(per); break; }
            if per.dim.dim.is_some() {
                if let Some(idxs)=per.dim.indices() { if idxs.iter().any(|idx| expand_dim_name(&per.name, idx)==parts[0]) { per_found=Some(per); break; } }
            }
        }
        let Some(per)=per_found else { return Err(anyhow!("{} {} not found", kind_name, df)); };
        let mut segments=vec![util::ident(parts[0], ctx.config, "peripheral_mod")];
        let mut cur_items: Vec<RegisterCluster> = per.registers.clone().unwrap_or_default();
        let mut target: Option<RegisterCluster>=None;
        for (i,part) in parts.iter().enumerate().skip(1) {
            let Some(rc)=find_in_items_by_name_or_expanded(&cur_items, part).cloned() else { return Err(anyhow!("{} {} not found", kind_name, df)); };
            if i==parts.len()-1 {
                let is_cluster=matches!(rc, RegisterCluster::Cluster(_));
                if is_cluster!=want_cluster { return Err(anyhow!("{} {} not found", kind_name, df)); }
                target=Some(rc);
            } else {
                match rc {
                    RegisterCluster::Cluster(c)=>{ segments.push(util::ident(part, ctx.config, "cluster_mod")); cur_items=c.children.clone(); }
                    _=>return Err(anyhow!("{} {} not found", kind_name, df))
                }
            }
        }
        return Ok(ExternalTarget{ parent_segments:segments, target:target.unwrap() });
    }
    // Single name: search whole device
    fn search_items(items:&[RegisterCluster], name:&str, want_cluster:bool, segs:&[Ident], ctx:&BlockContext) -> Option<ExternalTarget> {
        for rc in items {
            let is_cluster=matches!(rc, RegisterCluster::Cluster(_));
            if rc.name()==name && is_cluster==want_cluster { return Some(ExternalTarget{ parent_segments:segs.to_vec(), target:rc.clone() }); }
            if let RegisterCluster::Cluster(c)=rc {
                let mut ns=segs.to_vec(); ns.push(util::ident(&name_without_dim(&c.name), ctx.config, "cluster_mod"));
                if let Some(found)=search_items(&c.children, name, want_cluster, &ns, ctx) { return Some(found); }
            }
        }
        None
    }
    for per in &ctx.device.peripherals {
        if let Some(registers)=&per.registers {
            let segs=vec![util::ident(&name_without_dim(&per.name), ctx.config, "peripheral_mod")];
            if let Some(found)=search_items(registers, df, want_cluster, &segs, ctx) { return Ok(found); }
        }
    }
    Err(anyhow!("{} {} not found", kind_name, df))
}
fn render_external_derived(drc:&RegisterCluster, ext:&ExternalTarget, ctx:&BlockContext) -> TokenStream {
    let (base_ty, base_mod, _) = rc_type_and_name(&ext.target, ctx.config);
    let (der_ty, der_mod, _) = rc_type_and_name(drc, ctx.config);
    let segs=&ext.parent_segments;
    match drc {
        RegisterCluster::Register(_)=>{
            quote!{ pub use crate::#(#segs::)*#base_ty as #der_ty; pub use crate::#(#segs::)*#base_mod as #der_mod; }
        }
        RegisterCluster::Cluster(dc)=>{
            let ddesc=dc.description.as_deref().map(util::clean_description).unwrap_or_else(|| dc.name.clone());
            quote!{ #[doc=#ddesc] pub use crate::#(#segs::)*#base_ty as #der_ty; pub use crate::#(#segs::)*#base_mod as #der_mod; }
        }
    }
}
