        let Some(per)=per_found else { return Err(anyhow!("{} {} not found", kind_name, df)); };
        let mut segments=vec![util::ident(parts[0], ctx.config, "peripheral_mod")];
        let mut cur_items: Vec<RegisterCluster> = per.registers.clone().unwrap_or_default();
        let mut target: Option<RegisterCluster>=None;
        for (i,part) in parts.iter().enumerate().skip(1) {
            let Some(rc)=find_in_items_by_name_or_expanded(&cur_items, part).cloned() else { return Err(anyhow!("{} {} not found", kind_name, df)); };
