p="src/generate/peripheral.rs"; s=open(p).read()
# resolve_rc_size: max cluster size for cluster with dim
old="""        RegisterCluster::Cluster(c)=>{
            if let Some(base_name)=&c.derived_from {
                if let Some(t)=find_rc_by_path(base_name, ctx, siblings) { return resolve_rc_size(t, defaults, ctx, siblings); }
            }
            let child_defaults=c.properties.merge(defaults);
            cluster_size(c, &child_defaults, ctx)
        }"""
new="""        RegisterCluster::Cluster(c)=>{
            if ctx.config.max_cluster_size && c.dim.dim.is_some() {
                if let Some(inc)=c.dim.dim_increment { return Ok(inc); }
            }
            if let Some(base_name)=&c.derived_from {
                if let Some(t)=find_rc_by_path(base_name, ctx, siblings) { return resolve_rc_size(t, defaults, ctx, siblings); }
            }
            let child_defaults=c.properties.merge(defaults);
            cluster_size(c, &child_defaults, ctx)
        }"""
assert old in s; s=s.replace(old,new)
# But note if max and alias derived cluster with dim, size should maybe base? ignore
# cluster_size function: when computing child end for a dim child, our code in array branch uses elem_size*dim for array; if max cluster_size, elem_size already incl from resolve_rc_size; existing branch explicit max uses increment*dim – fine.
# In render_block_struct: validate dim cluster increment < elem actual size for non-max mode, and keep_list doc adjustments.
# At entry expansion, after elem_size computed and before dim handling, insert validation for clusters when dim_increment Some and elem_size>increment and not max_cluster_size.
old2="""        let dim_elem=rc.dim();
        if let Some(dim)=dim_elem.dim {"""
new2="""        let dim_elem=rc.dim();
        if let Some(dim)=dim_elem.dim {
            if !ctx.config.max_cluster_size {
                if let RegisterCluster::Cluster(cl)=rc {
                    if let Some(inc)=dim_elem.dim_increment {
                        if elem_size>inc {
                            let aub = if ctx.device.address_unit_bits==0 {8} else {ctx.device.address_unit_bits};
                            return Err(anyhow!(format!("Cluster {} has size {} bits that is more then array increment {} bits", cl.name, (elem_size as u128)*(aub as u128), (inc as u128)*(aub as u128))).context(format!("can't expand cluster '{}'", cl.name)).context("Could not expand register or cluster block"));
                        }
                    }
                }
            }"""
assert old2 in s; s=s.replace(old2,new2)
# Keep-list doc for clusters: in keep_list expansion entries.push currently doc_offset:offset (original). Adjust based on rc type: clusters use actual offset & doc_end
old3="""                    entries.push(BlockEntry{ offset: offset + (i as u32)*increment, size_bytes:elem_size, doc_offset:offset, doc_end:None, desc:desc.clone(), accessor_base_name:acc_base, ty:ty.clone(), kind:BlockKind::Single{field}, orig_index:idx });"""
new3="""                    let (k_doc_offset,k_doc_end)=match rc { RegisterCluster::Cluster(_)=>(offset + (i as u32)*increment, if elem_size>4 { Some(offset + (i as u32)*increment + elem_size) } else { None }), _=>(offset,None) };
                    entries.push(BlockEntry{ offset: offset + (i as u32)*increment, size_bytes:elem_size, doc_offset:k_doc_offset, doc_end:k_doc_end, desc:desc.clone(), accessor_base_name:acc_base, ty:ty.clone(), kind:BlockKind::Single{field}, orig_index:idx });"""
assert old3 in s; s=s.replace(old3,new3)
# render_cluster: pass force size via cluster_info; render_block_struct already receives Some(c). In BlockStructKind::Cluster branch, before constructing, compute force handling.
# We need cursor/end available: groups variable gives max end; compute actual_end = groups.iter().map(|g| g.end).max().unwrap_or(0)
# Insert just before `let debug_attr` in render_block_struct
old4="""    let debug_attr = if ctx.config.impl_debug {"""
new4="""    // For max_cluster_size, a dim cluster's struct is padded to its increment
    let mut trailing_reserved = TokenStream::new();
    if let BlockStructKind::Cluster{..} = &kind {
        if ctx.config.max_cluster_size {
            if let Some(ci)=cluster_info {
                if let Some(inc)=ci.dim.dim_increment {
                    if ci.dim.dim.is_some() {
                        let actual_end=groups.iter().map(|g| g.end).max().unwrap_or(0);
                        if actual_end>inc { return Err(anyhow!("Incorrect block size")); }
                        if inc>actual_end {
                            let lit=util::hex_literal((inc-actual_end) as u64);
                            trailing_reserved.extend(quote!{ _reserved_end: [u8; #lit], });
                        }
                    }
                }
            }
        }
    }
    let debug_attr = if ctx.config.impl_debug {"""
assert old4 in s; s=s.replace(old4,new4,1)
# In cluster struct quote, include trailing_reserved after struct_fields. Cluster branch uses `pub struct #ty { #struct_fields }` in two places (empty branch and normal). Replace in cluster branch only: easiest replace occurrences after debug_attr? We'll replace both cluster occurrences specifically by checking context strings.
s=s.replace("pub struct #ty { #struct_fields }\n                });", "pub struct #ty { #struct_fields #trailing_reserved }\n                });")
s=s.replace("pub struct #ty { #struct_fields }\n                impl #ty { #accessors }", "pub struct #ty { #struct_fields #trailing_reserved }\n                impl #ty { #accessors }")
open(p,"w").write(s)
print("ok")
PY
python3 /tmp/edit_cluster_max.py
cargo build --offline -q 2>&1 | tail -20
python3 /tmp/more2.py > /tmp/more2_results.txt 2>&1; grep "^FAIL" /tmp/more2_results.txt
