compare_case({"name":"clmax_small_default","svd":txt,"args":[]})
compare_case({"name":"clmax_small_max","svd":txt,"args":["--max-cluster-size"]})
compare_case({"name":"clmax_small_keep","svd":txt,"args":["--keep-list"]})
PY

