 u=f"<usage>{usage}</usage>" if usage else ""
 n=f"<name>{name}</name>" if name else ""
 return f"<enumeratedValues>{n}{u}<enumeratedValue><name>{valname}</name><description>{valname}</description><value>0</value></enumeratedValue></enumeratedValues>"
# This helper reg function from probe doesn't exist in this namespace, but fstring manual registers in show uses direct register string when False? It calls reg only in conditional expression evaluated? Python evaluates reg(...) regardless? conditional expression only evaluates chosen branch, False -> manual string.
