{"command":"cat > /tmp/edit_svd_field.py <<'PY'
p="src/svd.rs"; s=open(p).read()
# Add dim_index_text to DimElement with serde skip
old="""pub struct DimElement {
    pub dim: Option<u32>,
    pub dim_increment: Option<u32>,
    pub dim_index: Option<Vec<String>>,
    pub dim_name: Option<String>,
    pub dim_array_index: Option<DimArrayIndex>,
}"""
new="""pub struct DimElement {
    pub dim: Option<u32>,
    pub dim_increment: Option<u32>,
    pub dim_index: Option<Vec<String>>,
    #[serde(skip)]
    pub dim_index_text: Option<String>,
    pub dim_name: Option<String>,
    pub dim_array_index: Option<DimArrayIndex>,
}"""
assert old in s; s=s.replace(old,new)
# In parse_dim, set dim_index_text raw text cloned
old="""    let dim_index = match node.get_child("dimIndex") {
        Some(ch) => match ch.text() { Some(t)=>Some(parse_dim_index_text(t)), None=>None },
        None=>None
    };"""
new="""    let dim_index_text = node.get_child("dimIndex").and_then(|ch| ch.text()).map(|t| t.to_string());
    let dim_index = match &dim_index_text { Some(t)=>Some(parse_dim_index_text(t)), None=>None };"""
assert old in s; s=s.replace(old,new)
s=s.replace("Ok(DimElement{dim, dim_increment, dim_index, dim_name, dim_array_index})", "Ok(DimElement{dim, dim_increment, dim_index, dim_index_text, dim_name, dim_array_index})")
# Replace bitrange computation in parse_field. Find segment from let bit_offset_opt to let access
start=s.find("    let bit_offset_opt=get_opt_int::<u32>(node,\"bitOffset\")")
end=s.find("    let access=get_opt_access(node)", start)
seg='''    // Bit range determination with original precedence: bitRange > lsb/msb > bitOffset/bitWidth
    let (bit_offset, bit_width) = if let Some(br_text)=child_text(node, "bitRange") {
        let parse_err = |kind:&str| anyhow!(format!("Bit range invalid, {}", kind)).context(parsing_ctx("field",Some(&name),node));
        if !(br_text.starts_with('[') && br_text.ends_with(']')) {
            return Err(parse_err("Syntax"));
        }
        let inner=&br_text[1..br_text.len()-1];
        let mut split=inner.splitn(2, ':');
        let msb_s=split.next().unwrap_or("");
        let lsb_s=split.next().unwrap_or("");
        if split.next().is_some() {
            // splitn(2) won't have next, but a second ':' inside lsb_s will fail int parse below
        }
        let msb:u32 = match msb_s.parse() { Ok(v)=>v, Err(_)=>return Err(parse_err("ParseError")) };
        let lsb:u32 = match lsb_s.parse() { Ok(v)=>v, Err(_)=>return Err(parse_err("ParseError")) };
        if msb<lsb { return Err(parse_err("Size")); }
        (lsb, msb-lsb+1)
    } else if child_text(node,"lsb").is_some() && child_text(node,"msb").is_some() {
        let lsb_raw=parse_svd_int_raw(&child_text(node,"lsb").unwrap()).and_then(int_convert::<u32>);
        let msb_raw=parse_svd_int_raw(&child_text(node,"msb").unwrap()).and_then(int_convert::<u32>);
        match (lsb_raw, msb_raw) {
            (Ok(l),Ok(m))=>{
                if m<l { return Err(anyhow!("Bit range invalid, Size").context(parsing_ctx("field",Some(&name),node))); }
                (l, m-l+1)
            }
            _=>return Err(anyhow!("Bit range invalid, MsbLsb").context(parsing_ctx("field",Some(&name),node)))
        }
    } else if child_text(node,"bitOffset").is_some() && child_text(node,"bitWidth").is_some() {
        let off_raw=parse_svd_int_raw(&child_text(node,"bitOffset").unwrap()).and_then(int_convert::<u32>);
        let wid_raw=parse_svd_int_raw(&child_text(node,"bitWidth").unwrap()).and_then(int_convert::<u32>);
        match (off_raw, wid_raw) {
            (Ok(o),Ok(w))=>{
                if w==0 { return Err(anyhow!("`BitRange error: bitRange width of 0 does not make sense").context(parsing_ctx("field",Some(&name),node))); }
                (o,w)
            }
            _=>return Err(anyhow!("Bit range invalid, ParseError").context(parsing_ctx("field",Some(&name),node)))
        }
    } else {
        return Err(anyhow!("Bit range invalid, Syntax").context(parsing_ctx("field",Some(&name),node)));
    };
'''
s=s[:start]+seg+s[end:]
# Enum out of range validation after enums parsed: in parse_field, after enums loop before check_dim
old="""    check_dim_placeholder(&name,&dim,"field","field",node)?;"""
new="""    // Enumerated value range validation
    for ev in &enums {
        if ev.derived_from.is_none() {
            for v in &ev.values {
                if let Some(val)=v.value {
                    if bit_width<64 && val >= (1u64<<bit_width) {
                        let max=(1u64<<bit_width)-1;
                        return Err(anyhow!(format!("`EnumeratedValue error: Value {} out of range [0 - {}]", val, max)).context(parsing_ctx("field",Some(&name),node)));
                    }
                }
            }
        }
    }
    check_dim_placeholder(&name,&dim,"field","field",node)?;"""
assert old in s; s=s.replace(old,new,1)
open(p,"w").write(s)
print("ok")
PY
python3 /tmp/edit_svd_field.py
cargo build --offline -q 2>&1 | tail -30"}

