{"command":"cat > /tmp/edit_fielddim.py <<'PY'
p="src/generate/register.rs"; s=open(p).read()
# Insert variable reader expr helper before reader_expr function
pos=s.find("fn reader_expr(")
helper='''
fn offset_expr_var(base:u32, inc:u32, parenthesize:bool) -> TokenStream {
    let b=Literal::u32_unsuffixed(base); let i=Literal::u32_unsuffixed(inc);
    let inner=match (base,inc) {
        (0,1)=>quote!{n},
        (_,1)=>quote!{n + #b},
        (0,_)=>quote!{n * #i},
        (_,_)=>quote!{n * #i + #b},
    };
    if parenthesize && !matches!((base,inc),(0,1)) { quote!{(#inner)} } else { inner }
}
fn reader_expr_var(base:u32, inc:u32, width:u32, reg_size:u32) -> TokenStream {
    fn ty_bits(b:u32)->u32 { match b { 0..=8=>8, 9..=16=>16, 17..=32=>32, _=>64 } }
    let reg_ty_bits=ty_bits(reg_size); let field_ty_bits=ty_bits(width);
    let off=offset_expr_var(base,inc,true);
    if width==1 {
        let one=Literal::from_str("1").unwrap();
        return quote!{ ((self.bits >> #off) & #one) != 0 };
    }
    let shifted=quote!{ (self.bits >> #off) };
    let mask:u128=if width>=128 {u128::MAX} else {(1u128<<width)-1};
    let mask_lit=if mask<10 { Literal::from_str(&mask.to_string()).unwrap() } else { util::hex_literal(mask as u64) };
    let masked=if width==reg_ty_bits { shifted } else { quote!{ #shifted & #mask_lit } };
    if field_ty_bits!=reg_ty_bits { let ty=bits_to_ty(width).unwrap(); quote!{ (#masked) as #ty } } else { masked }
}
'''
s=s[:pos]+helper+s[pos:]
# Replace accessor instances loop. Find marker
start=s.find("        // accessors in R/W impls per instance")
end=s.find("    }\n    if field_ctxs.is_empty()", start)
# Actually after loop there may not that exact due safety changes; locate "\n    // Also if writable fields" or spec doc second
for marker in ["    // Also if writable fields", "    let desc2 ="]:
    idx=s.find(marker,start)
    if idx!=-1:
        end=idx; break
seg='''        // accessors in R/W impls (array accessors for dim fields, then individual instances where applicable)
        let is_dim_array = f.dim.dim.is_some() && !config.keep_list;
        if is_dim_array {
            let dim=f.dim.dim.unwrap();
            let dim_lit=Literal::u32_unsuffixed(dim);
            let inc=f.dim.dim_increment.unwrap_or(f.bit_width);
            let base_accessor=util::ident(&field_without_dim(f), config, "field_accessor");
            let first_expanded=fc.instances.get(0).map(|(n,_)| n.clone()).unwrap_or_default();
            let warn=format!("<div class=\\"warning\\">`n` is number of field in register. `n == 0` corresponds to `{}` field.</div>", first_expanded);
            if fc.can_read {
                let expr=reader_expr_var(f.bit_offset, inc, f.bit_width, props.size);
                let iter_name=util::ident_raw(&format!("{}_iter", base_accessor.to_string()));
                r_methods.extend(quote!{
                    #[doc=#fdesc] #[doc=""] #[doc=#warn] #[inline(always)] pub fn #base_accessor(&self, n: u8) -> #field_reader_ty { #[allow(clippy::no_effect)] [(); #dim_lit][n as usize]; #field_reader_ty::new(#expr) }
                    #[doc="Iterator for array of:"] #[doc=#fdesc] #[inline(always)] pub fn #iter_name(&self) -> impl Iterator<Item=#field_reader_ty> + '_ { (0..#dim_lit).map(move |n| #field_reader_ty::new(#expr)) }
                });
            }
            if fc.can_write {
                let off_expr=offset_expr_var(f.bit_offset, inc, false);
                w_methods.extend(quote!{
                    #[doc=#fdesc] #[doc=""] #[doc=#warn] #[inline(always)] pub fn #base_accessor(&mut self, n: u8) -> #field_writer_ty<'_, #reg_spec> { #[allow(clippy::no_effect)] [(); #dim_lit][n as usize]; #field_writer_ty::new(self, #off_expr) }
                });
            }
        }
        let indices_seq = f.dim.indices().map(|idxs| idxs.iter().enumerate().all(|(i,v)| v==&i.to_string())).unwrap_or(true);
        let placeholder_at_end = f.name.ends_with("[%s]") || f.name.ends_with("%s");
        let has_individual = !is_dim_array || (f.name.matches("%s").count()==1 && !(placeholder_at_end && indices_seq));
        if has_individual {
            for (inst_name, inst_off) in &fc.instances {
                let accessor = util::ident(inst_name, config, "field_accessor");
                let doc_bit = if f.description.as_deref().map(util::clean_description).filter(|s| !s.is_empty()).is_some() {
                    if f.bit_width==1 { format!("Bit {} - {}", inst_off, fdesc) } else { format!("Bits {}:{} - {}", inst_off, inst_off+f.bit_width-1, fdesc) }
                } else {
                    if f.bit_width==1 { format!("Bit {}", inst_off) } else { format!("Bits {}:{}", inst_off, inst_off+f.bit_width-1) }
                };
                if fc.can_read {
                    let expr = reader_expr(*inst_off, f.bit_width, props.size);
                    r_methods.extend(quote!{
                        #[doc=#doc_bit] #[inline(always)] pub fn #accessor(&self) -> #field_reader_ty { #field_reader_ty::new(#expr) }
                    });
                }
                if fc.can_write {
