pos=s.find("pub fn render(reg:&RegisterInfo")
helpers=r'''
#[derive(Clone)]
struct SourceFieldLoc {
    field: FieldInfo,
    reg_mod_path: Vec<Ident>,
    same_register: bool,
}
fn register_name_for_type(r:&RegisterInfo, config:&Config) -> String {
    let base=r.name.replace("[%s]", "").replace("%s", "");
    if !config.ignore_groups {
        if let Some(g)=&r.alternate_group { return format!("{}_{}", g, base); }
    }
    base
}
fn current_reg_mod_path(reg:&RegisterInfo, config:&Config, path:&str) -> Vec<Ident> {
    let comps:Vec<&str>=path.split('.').collect();
    let mut segs=Vec::new();
    for (i,c) in comps.iter().enumerate() {
        if i==0 { segs.push(util::ident(&c.replace("[%s]", "").replace("%s", ""), config, "peripheral_mod")); }
        else { segs.push(util::ident(&c.replace("[%s]", "").replace("%s", ""), config, "cluster_mod")); }
    }
    segs.push(util::ident(&register_name_for_type(reg, config), config, "register_mod"));
    segs
}
fn relative_path(current:&[Ident], target:&[Ident]) -> TokenStream {
    if current==target { return TokenStream::new(); }
    if current.get(0).map(|i| i.to_string()) != target.get(0).map(|i| i.to_string()) {
        return quote!{ crate::#(#target::)* };
    }
    let mut common=0;
    while common<current.len() && common<target.len() && current[common].to_string()==target[common].to_string() { common+=1; }
    let ups=current.len()-common;
    let mut out=TokenStream::new();
    for _ in 0..ups { out.extend(quote!{ super:: }); }
    for seg in &target[common..] { out.extend(quote!{ #seg:: }); }
    out
}
fn find_peripheral_for_path<'a>(device:&'a Device, name:&str) -> Option<&'a Peripheral> {
    for per in &device.peripherals {
        if per.name==name { return Some(per); }
        if per.dim.dim.is_some() {
            if let Some(idxs)=per.dim.indices() { if idxs.iter().any(|idx| per.name.replace("[%s]", idx).replace("%s", idx)==name) { return Some(per); } }
        }
    }
    None
}
fn resolve_field_path(df:&str, reg:&RegisterInfo, config:&Config, path:&str, device:&Device) -> anyhow::Result<SourceFieldLoc> {
    let cur_path=current_reg_mod_path(reg, config, path);
    if !df.contains('.') {
        if let Some(fields)=&reg.fields {
            if let Some(f)=fields.iter().find(|f| f.name==df) {
                return Ok(SourceFieldLoc{ field:f.clone(), reg_mod_path:cur_path, same_register:true });
            }
        }
        return Err(anyhow!("field {} not found", df));
    }
    let parts:Vec<&str>=df.split('.').collect();
    if parts.len()<3 { panic!("Full qualifying field path is expected"); }
    let Some(per)=find_peripheral_for_path(device, parts[0]) else { return Err(anyhow!("field {} not found", df)); };
    let mut segs=vec![util::ident(parts[0], config, "peripheral_mod")];
    let mut items: Vec<RegisterCluster> = per.registers.clone().unwrap_or_default();
    // parts[1..len-2] clusters, parts[len-2] register, parts[len-1] field
    let reg_idx=parts.len()-2;
    for part in &parts[1..reg_idx] {
        let Some(rc)=items.iter().find(|rc| rc.name()==*part).cloned() else { return Err(anyhow!("field {} not found", df)); };
        match rc { RegisterCluster::Cluster(c)=>{ segs.push(util::ident(&c.name.replace("[%s]", "").replace("%s", ""), config, "cluster_mod")); items=c.children.clone(); } _=>return Err(anyhow!("field {} not found", df)) }
    }
    let Some(target_reg_rc)=items.iter().find(|rc| rc.name()==parts[reg_idx]).cloned() else { return Err(anyhow!("field {} not found", df)); };
    let RegisterCluster::Register(target_reg)=target_reg_rc else { return Err(anyhow!("field {} not found", df)); };
    segs.push(util::ident(&register_name_for_type(&target_reg, config), config, "register_mod"));
    let field_name=parts[parts.len()-1];
    let Some(f)=target_reg.fields.as_ref().and_then(|fs| fs.iter().find(|f| f.name==field_name)) else { return Err(anyhow!("field {} not found", df)); };
    let same = segs==cur_path;
    Ok(SourceFieldLoc{ field:f.clone(), reg_mod_path:segs, same_register:same })
}
fn field_path_debug(reg:&RegisterInfo, field_name:&str, path:&str) -> String {
    let comps:Vec<&str>=path.split('.').collect();
    let per=comps.get(0).cloned().unwrap_or("");
    let clusters:Vec<String>=comps.iter().skip(1).map(|s| format!("\"{}\"", s)).collect();
    format!("FieldPath {{ register: RegisterPath {{ block: BlockPath {{ peripheral: \"{}\", path: [{}] }}, name: \"{}\" }}, name: \"{}\" }}", per, clusters.join(", "), reg.name, field_name)
}
fn resolve_ev_path(df:&str, reg:&RegisterInfo, cur_field:&FieldInfo, config:&Config, path:&str, device:&Device) -> anyhow::Result<(SourceFieldLoc, EnumeratedValues)> {
    // Simple name: search current register fields for EV name/header
    if !df.contains('.') {
        if let Some(fields)=&reg.fields {
            for f in fields {
                for ev in &f.enumerated_values {
                    if ev.name.as_deref()==Some(df) || ev.header_enum_name.as_deref()==Some(df) {
                        return Ok((SourceFieldLoc{ field:f.clone(), reg_mod_path:current_reg_mod_path(reg,config,path), same_register:true }, ev.clone()));
                    }
                }
            }
        }
        return Err(anyhow!("enumeratedValues {} not found, parent field: {}", df, field_path_debug(reg,&cur_field.name,path)));
    }
    // Full path: peripheral.(clusters).register.field.enum ; split last as enum, rest as field path
    let parts:Vec<&str>=df.split('.').collect();
    if parts.len()<4 {
        // Try within-register Field.Enum form
        if parts.len()==2 {
            if let Some(fields)=&reg.fields {
                if let Some(f)=fields.iter().find(|f| f.name==parts[0]) {
                    if let Some(ev)=f.enumerated_values.iter().find(|ev| ev.name.as_deref()==Some(parts[1]) || ev.header_enum_name.as_deref()==Some(parts[1])) {
                        return Ok((SourceFieldLoc{ field:f.clone(), reg_mod_path:current_reg_mod_path(reg,config,path), same_register:true }, ev.clone()));
                    }
                }
            }
        }
        // Original panics for partial full paths in many cases; treat as not found if not resolved above
        return Err(anyhow!("enumeratedValues {} not found, parent field: {}", df, field_path_debug(reg,&cur_field.name,path)));
    }
    let field_df=parts[..parts.len()-1].join(".");
    let enum_name=parts[parts.len()-1];
    let src=match resolve_field_path(&field_df, reg, config, path, device) {
        Ok(v)=>v,
        Err(_)=>return Err(anyhow!("enumeratedValues {} not found, parent field: {}", df, field_path_debug(reg,&cur_field.name,path)))
    };
    if let Some(ev)=src.field.enumerated_values.iter().find(|ev| ev.name.as_deref()==Some(enum_name) || ev.header_enum_name.as_deref()==Some(enum_name)) {
        return Ok((src, ev.clone()));
    }
    Err(anyhow!("enumeratedValues {} not found, parent field: {}", df, field_path_debug(reg,&cur_field.name,path)))
}
fn select_evs<'a>(evs:&'a [EnumeratedValues]) -> (Option<&'a EnumeratedValues>, Option<&'a EnumeratedValues>) {
    let first=evs.first();
    let r=evs.iter().find(|ev| ev.usage==Some(Usage::Read)).or(first);
    let w=evs.iter().find(|ev| ev.usage==Some(Usage::Write)).or(first);
    (r,w)
}
fn source_enum_ident(src_field:&FieldInfo, target_ev:&EnumeratedValues, config:&Config, for_write:bool) -> Ident {
    let (r,w)=select_evs(&src_field.enumerated_values);
    let same=match (r,w) { (Some(a),Some(b))=>std::ptr::eq(a,b), _=>false };
    let base=enum_base_name(src_field, target_ev, config);
    if same { util::ident(&base, config, "enum_name") } else if for_write { util::ident(&base, config, "enum_write_name") } else { util::ident(&base, config, "enum_read_name") }
}
