#[derive(Debug, Clone)]
enum SerBitRange { Range(u32,u32), MsbLsb(u32,u32), OffsetWidth(u32,u32) }
impl<'de> Deserialize<'de> for SerBitRange {
    fn deserialize<D: Deserializer<'de>>(d:D) -> Result<Self,D::Error> {
        #[derive(Deserialize)]
        #[serde(rename_all="camelCase")]
        struct Raw {
            bit_range: Option<Cap<String>>,
            lsb: Option<Cap<u32>>,
            msb: Option<Cap<u32>>,
            bit_offset: Option<Cap<u32>>,
            bit_width: Option<Cap<u32>>,
        }
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Cap<T> { Val(T), Other(serde::de::IgnoredAny) }
        let raw=Raw::deserialize(d).map_err(|_| serde::de::Error::custom("data did not match any variant of untagged enum SerBitRange"))?;
        if let Some(br)=raw.bit_range {
            return match br {
                Cap::Val(st)=>{
                    let inner=st.strip_prefix('[').and_then(|x| x.strip_suffix(']')).ok_or_else(|| serde::de::Error::custom("Can't parse bitRange"))?;
                    let (a,b)=inner.split_once(':').ok_or_else(|| serde::de::Error::custom("Can't parse bitRange"))?;
                    let msb:u32=a.parse().map_err(|_| serde::de::Error::custom("Can't parse bitRange"))?;
                    let lsb:u32=b.parse().map_err(|_| serde::de::Error::custom("Can't parse bitRange"))?;
                    if msb<lsb { return Err(serde::de::Error::custom("Can't parse bitRange")); }
                    Ok(SerBitRange::Range(lsb, msb-lsb+1))
                }
                Cap::Other(_)=>Err(serde::de::Error::custom("data did not match any variant of untagged enum SerBitRange"))
            };
        }
        if let (Some(Cap::Val(l)), Some(Cap::Val(m)))=(raw.lsb, raw.msb) {
            if m<l { return Err(serde::de::Error::custom("data did not match any variant of untagged enum SerBitRange")); }
            return Ok(SerBitRange::MsbLsb(l,m));
        }
        if let (Some(Cap::Val(o)), Some(Cap::Val(w)))=(raw.bit_offset, raw.bit_width) {
            return Ok(SerBitRange::OffsetWidth(o,w));
        }
        Err(serde::de::Error::custom("data did not match any variant of untagged enum SerBitRange"))
    }
