        let (bit_offset, bit_width)=match h.bit_range {
            SerBitRange::Range(o,w)=>(o,w),
            SerBitRange::OffsetWidth(o,w)=>(o,w),
            SerBitRange::MsbLsb(l,m)=>(l, m-l+1),
        };
        Ok(FieldInfo{ derived_from:h.derived_from, dim:h.dim, name:h.name, description:h.description, bit_offset, bit_width, access:h.access, enumerated_values:h.enumerated_values, write_constraint:h.write_constraint, read_action:h.read_action, modified_write_values:h.modified_write_values })
    }
}
