fn raw_ident(name:&str) -> Ident { Ident::new(name, proc_macro2::Span::call_site()) }
fn enum_tokens(items:&[RiscvEnumItem], doc_text:&'static str, pac_trait:&str, enum_name:&str, config:&Config) -> TokenStream {
    let variants=items.iter().map(|it| {
        let id=raw_ident(&it.name);
        let val=Literal::usize_unsuffixed(it.value);
        let desc=it.description.as_deref().map(util::clean_description).filter(|s| !s.is_empty()).unwrap_or_else(|| it.name.clone());
        let doc=format!("{} - {}", it.value, desc);
        quote!{ #[doc=#doc] #id = #val, }
    });
    let pac_ident=raw_ident(pac_trait);
    let enum_ident=raw_ident(enum_name);
    let defmt=match &config.impl_defmt { Some(f)=>quote!{ #[cfg_attr(feature=#f, derive(defmt::Format))] }, None=>quote!{} };
    quote!{
        #[doc=#doc_text]
        #[riscv::pac_enum(unsafe #pac_ident)]
        #defmt
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum #enum_ident { #(#variants)* }
    }
}

pub fn render_new(device:&Device, config:&Config, interrupts:&[InterruptInfo]) -> TokenStream {
    let _=device;
    let rc=config.settings.riscv_config.as_ref().unwrap();
    let core_tokens: TokenStream = if !rc.core_interrupts.is_empty() {
        enum_tokens(&rc.core_interrupts, r" Core interrupts. These interrupts are handled by the core itself.", "CoreInterruptNumber", "CoreInterrupt", config)
    } else { quote!{ pub use riscv::interrupt::Interrupt as CoreInterrupt; } };
    let exc_tokens: TokenStream = if !rc.exceptions.is_empty() {
        enum_tokens(&rc.exceptions, r" Exception sources in the device.", "ExceptionNumber", "Exception", config)
    } else { quote!{ pub use riscv::interrupt::Exception; } };
    let prio_tokens: TokenStream = if !rc.priorities.is_empty() {
        enum_tokens(&rc.priorities, r" Priority levels in the device", "PriorityNumber", "Priority", config)
    } else { quote!{} };
    let hart_tokens: TokenStream = if !rc.harts.is_empty() {
        enum_tokens(&rc.harts, r" HARTs in the device", "HartIdNumber", "Hart", config)
    } else { quote!{} };
    let external_tokens: TokenStream = if !interrupts.is_empty() {
        let variants=interrupts.iter().map(|i| {
            let id=&i.ident; let val=Literal::u32_unsuffixed(i.value); let doc=format!("{} - {}", i.value, i.desc);
            quote!{ #[doc=#doc] #id = #val, }
        });
        let defmt=match &config.impl_defmt { Some(f)=>quote!{ #[cfg_attr(feature=#f, derive(defmt::Format))] }, None=>quote!{} };
        quote!{
            #[doc=r" External interrupts. These interrupts are handled by the external peripherals."]
            #[riscv::pac_enum(unsafe ExternalInterruptNumber)]
            #defmt
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum ExternalInterrupt { #(#variants)* }
        }
    } else { quote!{} };
    let plic_handler: TokenStream = if let Some(plic)=&rc.plic {
        if let Some(core_int)=&plic.core_interrupt {
            let core_ident=raw_ident(core_int);
            let plic_ty=util::ident(&plic.name, config, "peripheral");
            let ctx_tokens: TokenStream = if let Some(hart)=&plic.hart_id {
                let hart_ident=raw_ident(hart);
                quote!{ ctx(Hart::#hart_ident) }
            } else { quote!{ ctx_mhartid() } };
            quote!{
                #[cfg(feature="rt")]
                #[riscv_rt::core_interrupt(CoreInterrupt::#core_ident)]
                unsafe fn plic_handler() {
                    let plic = unsafe { crate::#plic_ty::steal() };
                    let claim = plic.#ctx_tokens.claim();
                    if let Some(s) = claim.claim::<ExternalInterrupt>() {
                        unsafe { _dispatch_external_interrupt(s.number()) }
                        claim.complete(s);
                    }
                }
            }
        } else { quote!{} }
    } else { quote!{} };
    quote!{
        #[doc=r" Interrupt numbers, priority levels, and HART IDs."]
        pub mod interrupt {
            #core_tokens
            #exc_tokens
            #prio_tokens
            #hart_tokens
            pub use riscv::{InterruptNumber, ExceptionNumber, PriorityNumber, HartIdNumber, interrupt::{enable, disable, free, nested}};
            pub type Trap = riscv::interrupt::Trap<CoreInterrupt, Exception>;
            #[doc=r" Retrieves the cause of a trap in the current hart."]
            #[doc=r""]
            #[doc=r" If the raw cause is not a valid interrupt or exception for the target, it returns an error."]
            #[inline] pub fn try_cause() -> riscv::result::Result<Trap> { riscv::interrupt::try_cause() }
            #[doc=r" Retrieves the cause of a trap in the current hart (machine mode)."]
            #[doc=r""]
            #[doc=r" If the raw cause is not a valid interrupt or exception for the target, it panics."]
            #[inline] pub fn cause() -> Trap { try_cause().unwrap() }
            #external_tokens
            #plic_handler
        }
    }
}

pub fn device_x_new(config:&Config, interrupts:&[InterruptInfo]) -> String {
    let rc=config.settings.riscv_config.as_ref().unwrap();
    let mut s=String::new();
    if !rc.core_interrupts.is_empty() {
        s.push_str("/* Core interrupt sources and trap handlers */\n");
        for it in &rc.core_interrupts {
            s.push_str(&format!("PROVIDE({} = DefaultHandler);\n", it.name));
            s.push_str(&format!("PROVIDE(_start_{}_trap = _start_DefaultHandler_trap);\n", it.name));
        }
    }
    if !rc.exceptions.is_empty() {
        s.push_str("/* Exception sources */\n");
        for it in &rc.exceptions { s.push_str(&format!("PROVIDE({} = ExceptionHandler);\n", it.name)); }
    }
    if !interrupts.is_empty() {
        s.push_str("/* External interrupt sources */\n");
        for i in interrupts { s.push_str(&format!("PROVIDE({} = DefaultHandler);\n", i.name)); }
    }
    s
}

fn steal_impl(ty:&Ident) -> TokenStream {
    quote!{
        impl #ty {
            /// Steal an instance of this peripheral
            ///
            /// # Safety
            ///
            /// Ensure that the new instance of the peripheral cannot be used in a way
            /// that may race with any existing instances, for example by only
            /// accessing read-only or write-only registers, or by consuming the
            /// original peripheral and using critical sections to coordinate
            /// access between multiple new instances.
            ///
            /// Additionally, other software such as HALs may rely on only one
            /// peripheral instance existing to ensure memory safety; ensure
            /// no stolen instances are passed to such software.
            #[inline]
            pub unsafe fn steal() -> Self { Self::new() }
        }
    }
}

pub fn render_clint_plic(device:&Device, config:&Config) -> TokenStream {
    let rc=config.settings.riscv_config.as_ref().unwrap();
    let mut out=TokenStream::new();
    if let Some(clint)=&rc.clint {
        let per=device.peripherals.iter().find(|p| p.name==clint.name).unwrap();
        let ty=util::ident(&per.name, config, "peripheral");
        let base_lit=Literal::from_str(&format!("0x{:X}", per.base_address)).unwrap();
        let freq=Literal::usize_unsuffixed(clint.mtime_freq);
        let pub_tok=if clint.pub_new { quote!{pub} } else { quote!{} };
        let steal=steal_impl(&ty);
        out.extend(quote!{
            riscv_peripheral::clint_codegen!(#pub_tok #ty, base #base_lit, mtime_freq #freq,);
            #steal
        });
    }
    if let Some(plic)=&rc.plic {
        let per=device.peripherals.iter().find(|p| p.name==plic.name).unwrap();
        let ty=util::ident(&per.name, config, "peripheral");
        let base_lit=Literal::from_str(&format!("0x{:X}", per.base_address)).unwrap();
        let pub_tok=if plic.pub_new { quote!{pub} } else { quote!{} };
        let steal=steal_impl(&ty);
        out.extend(quote!{
            riscv_peripheral::plic_codegen!(#pub_tok #ty, base #base_lit,);
            #steal
        });
    }
    out
}
