# Add comment/pi parsing helpers inside impl Parser before skip_misc
pos=s.find("    fn skip_misc(")
helpers=r'''
    fn parse_pi(&mut self) -> Result<(),String> {
        // self.pos at "<?"
        match self.s[self.pos..].find("?>") {
            Some(i)=>{ self.pos+=i+2; Ok(()) }
            None=>Err(err_at(self.s, self.s.len(), "expected '?>'".into()))
        }
    }
    fn parse_comment(&mut self) -> Result<(),String> {
        match self.s[self.pos..].find("-->") {
            Some(i)=>{ self.pos+=i+3; Ok(()) }
            None=>Err(err_at(self.s, self.s.len(), "expected '-->'".into()))
        }
    }
    fn skip_ws_count(&mut self) -> usize { let st=self.pos; self.skip_ws(); self.pos-st }
    fn parse_xml_decl(&mut self) -> Result<(),String> {
        // at "<?xml"
        self.pos+=5;
        if self.starts("?>") { self.pos+=2; return Ok(()); }
        // expect version as first pseudo-attribute
        let parse_pseudo = |p:&mut Self, expected:&str| -> Result<(),String> {
            if !p.s[p.pos..].starts_with(expected) {
                return Err(err_at(p.s, p.pos, format!("expected '{}'", expected)));
            }
            p.pos+=expected.len();
            p.skip_ws();
            if p.peek()!=Some(b'=') {
                let ch=p.peek().map(|b| b as char).unwrap_or('?');
                return Err(err_at(p.s, p.pos, format!("expected '=' not '{}'", ch)));
            }
            p.pos+=1; p.skip_ws();
            let q=p.peek();
            if q!=Some(b'"') && q!=Some(b'\'') {
                let ch=q.map(|b| b as char).unwrap_or('?');
                return Err(err_at(p.s, p.pos, format!("expected a quote not '{}'", ch)));
            }
            let qq=q.unwrap(); p.pos+=1;
            while let Some(b)=p.peek() { if b==qq { break; } p.pos+=1; }
            if p.peek()==Some(qq) { p.pos+=1; } else {
                return Err(err_at(p.s, p.pos, "expected a quote".into()));
            }
            Ok(())
        };
        // version is required if not immediate ?>
        self.skip_ws();
        parse_pseudo(self, "version")?;
        let mut seen_encoding=false; let mut seen_standalone=false;
        loop {
            let ws=self.skip_ws_count();
            if self.starts("?>") { self.pos+=2; return Ok(()); }
            if self.eof() { return Err(err_at(self.s, self.pos, "expected '?>'".into())); }
            if ws==0 {
                let ch=self.peek().map(|b| b as char).unwrap_or('?');
                return Err(err_at(self.s, self.pos, format!("expected a whitespace not '{}'", ch)));
            }
            if !seen_encoding && !seen_standalone && self.s[self.pos..].starts_with("encoding") {
                parse_pseudo(self, "encoding")?; seen_encoding=true;
            } else if !seen_standalone && self.s[self.pos..].starts_with("standalone") {
                parse_pseudo(self, "standalone")?; seen_standalone=true;
            } else {
                return Err(err_at(self.s, self.pos, "expected '?>'".into()));
            }
        }
    }
'''
s=s[:pos]+helpers+s[pos:]
# Replace skip_misc body to use parse_pi/comment and not swallow errors. Find fn skip_misc block and replace whole up to parse_element.
start=s.find("    fn skip_misc(")
