                self.parse_comment()?;''')
s=s.replace('''            } else if self.starts("<?") {
                match self.s[self.pos..].find("?>") { Some(i)=>{self.pos+=i+2;} None=>{self.pos=self.s.len();} }''', '''            } else if self.starts("<?") {
                self.parse_pi()?;''')
# parse_document: handle xml decl before skip_misc only if exact <?xml followed by ws or ?>
old='''    let mut p=Parser{s, bytes:s.as_bytes(), pos:0};
