use std::fmt;
#[derive(Debug,Deserialize)]
struct Reg { name:String }
#[derive(Debug)]
enum RC { Register(Reg), Cluster(Reg) }
impl<'de> Deserialize<'de> for RC {
 fn deserialize<D:Deserializer<'de>>(d:D)->Result<Self,D::Error> {
  struct V;
  impl<'de> Visitor<'de> for V {
   type Value=RC;
   fn expecting(&self,f:&mut fmt::Formatter)->fmt::Result { write!(f,"map with a single key") }
   fn visit_map<A:MapAccess<'de>>(self,mut map:A)->Result<RC,A::Error> {
     let Some(first_key)=map.next_key::<String>()? else { return Err(de::Error::invalid_value(de::Unexpected::Map,&"map with a single key")); };
     let mut result=None;
     match first_key.as_str() {
       "register"=>{ result=Some(RC::Register(map.next_value()?)); }
       "cluster"=>{ result=Some(RC::Cluster(map.next_value()?)); }
