     while let Some(_)=map.next_key::<IgnoredAny>()? { count+=1; let _=map.next_value::<IgnoredAny>()?; }
     if count!=1 { return Err(de::Error::invalid_value(de::Unexpected::Map,&"map with a single key")); }
     match result { Some(r)=>Ok(r), None=>Err(de::Error::unknown_variant(&first_key,&["register","cluster"])) }
   }
  }
  d.deserialize_map(V)
 }
